window.SUBJECTS = window.SUBJECTS || [];
window.SUBJECTS.push({"id":"eco","n":"Economy","tab":"Economy","w":"Static economy only: concepts, banking, planning and long-running schemes.","topics":[{"id":"basics","n":"Concepts and National Income","qs":[{"id":"q0003","q":"Which of the following Indian economists contributed to Human Development Index?","o":["Amartya Sen","Abhijit Banerjee","Amiya Kumar Bagchi","Avinash Dixit"],"a":0,"x":"The Human Development Index was built for UNDP in 1990 by Mahbub ul Haq, working with Amartya Sen, whose capability approach is its foundation.","e":"HDI combines three things: a long healthy life, knowledge (schooling) and a decent standard of living (income).","src":["ASO 18 Aug 2025 S1"]},{"id":"q0017","q":"The profit of a firm is also defined as:","o":["the difference between taxation and revenue","the difference between cost and profit","the difference between advertisement cost and revenue","the difference between cost and revenue"],"a":3,"x":"Profit is what is left after costs are taken out of revenue: Profit = Total Revenue − Total Cost.","e":"If a shop earns ₹1,000 from sales and spends ₹700, its profit is ₹300.","src":["ASO 18 Aug 2025 S1"]},{"id":"q0019","q":"The First Human Development Report was published in the year:","o":["1993","1990","1991","1992"],"a":1,"x":"UNDP published the first Human Development Report in 1990, with the HDI designed by Mahbub ul Haq and Amartya Sen.","e":"HDI measures health, education and income.","src":["ASO 18 Aug 2025 S1"]},{"id":"q0046","q":"______ are known as goods and services that are purchased by their ultimate user.","o":["Public goods","Production goods","Merit goods","Consumption goods"],"a":3,"x":"Consumption (final) goods are bought by the ultimate user for direct use, like food or a shirt. Goods used to make other goods are producer or capital goods.","e":"Flour bought by a household is a consumption good; the same flour bought by a bakery is an intermediate good.","src":["ASO 18 Aug 2025 S2"]},{"id":"q0055","q":"The Cobb-Douglas Production Function is applied to the:","o":["whole of the manufacturing industry","Banking and Finance Industry","Insurance Industry","Tourism Industry"],"a":0,"x":"Cobb and Douglas first tested their production function on data for the whole US manufacturing industry (1899–1922).","e":"Form: Q = A·L^a·K^b, where L is labour and K is capital.","src":["ASO 18 Aug 2025 S2"]},{"id":"q0059","q":"__________ is calculated by averaging the square of the poverty gap ratio.","o":["Hunger Index","Haq Index","Sen Index","Human Development Index"],"a":2,"x":"The Sen Index (Amartya Sen, 1976) combines how many people are poor, how far below the line they are, and inequality among the poor.","e":"Headcount ratio counts the poor; the poverty gap measures how far below the line they fall.","src":["ASO 18 Aug 2025 S2"],"k":"Strictly, averaging the squared poverty gap is the Foster–Greer–Thorbecke (P2) measure; DSSSB's key marks the Sen Index."},{"id":"q0093","q":"People who are always poor and the people who are usually poor but may sometimes have a little more money (example: casual workers) are grouped together as __________.","o":["churning poor","occasionally poor","chronic poor","transient poor"],"a":2,"x":"Chronic poor: people who are always poor, together with those usually poor who occasionally have a little more money, such as casual workers.","e":"Churning poor move in and out of poverty; occasionally poor are rich most of the time but may sometimes fall below the line.","src":["ASO 18 Aug 2025 S3"]},{"id":"q0138","q":"______________ refer to the benefits a firm or an individual causes to another for which they are not paid.","o":["Negative internalities","Negative externalities","Positive externalities","Positive internalities"],"a":2,"x":"A positive externality is a benefit that spills over to others without payment, like a beekeeper's bees pollinating a neighbour's orchard.","e":"A negative externality is a cost imposed on others, such as factory smoke.","src":["ASO 19 Aug 2025 S2"]},{"id":"q0163","q":"Which indicator is commonly used to measure educational attainment in a country?","o":["Infant mortality rate","Life expectancy","Gross Domestic Product","Literacy rate"],"a":3,"x":"Literacy rate is the standard indicator of educational attainment, and one of the inputs of the Human Development Index.","e":"Infant mortality and life expectancy measure health; GDP measures output.","src":["ASO 19 Aug 2025 S3"]},{"id":"q0209","q":"Who among the following developed 'Sen Index'?","o":["Bimal Roy Sen","Amartya Sen","Bipasha Sen","Radhakamal Sen"],"a":1,"x":"Amartya Sen developed the Sen Index (1976), a poverty measure combining headcount, the depth of the poverty gap, and inequality among the poor.","e":"Sen won the Nobel Prize in Economics in 1998 and the Bharat Ratna in 1999.","src":["ASO 20 Aug 2025 S1"]},{"id":"q0246","q":"Arrange the following Sustainable Development Goals (SDG) in ascending order of their SDG number. A. Equality of Education B. Clean Water and Sanitation C. Decent Work and Economic Growth D. Good Health and Well Being","o":["A-B-C-D","C-A-D-B","A-D-B-C","D-A-B-C"],"a":3,"x":"The goals in SDG number order: Good Health and Well-being (3), Quality Education (4), Clean Water and Sanitation (6), Decent Work and Economic Growth (8).","e":"There are 17 SDGs for 2015–2030; Goal 1 is No Poverty.","src":["ASO 20 Aug 2025 S2"]},{"id":"q0247","q":"What is the concept of disposable income?","o":["Disposable Income = Personal Income + (Personal Income Tax − Fees − Fines)","Disposable Income = Net Domestic Product − Public Income","Disposable Income = Personal Income − (Personal Income Tax + Fees + Fines)","Disposable Income = Personal Income + (Personal Income Tax + Fees + Fines)"],"a":2,"x":"Disposable income = personal income minus direct taxes and other compulsory payments (such as fees and fines). It is what households can spend or save.","e":"If personal income is ₹10 lakh and taxes and fees total ₹1.5 lakh, disposable income is ₹8.5 lakh.","src":["ASO 20 Aug 2025 S2"]},{"id":"q0255","q":"Which of the following is a major cause of poverty in India?","o":["High literacy rate","Declining population","Low birth rate","Low capital formation"],"a":3,"x":"Low capital formation — too little investment in machinery, infrastructure and skills — keeps productivity and incomes low, which causes poverty.","e":"High population growth and unemployment are also listed causes.","src":["ASO 20 Aug 2025 S2"]},{"id":"q0282","q":"___________ unemployment is a characteristic feature of Indian agriculture.","o":["Structural","Disguised","Frictional","Educated"],"a":1,"x":"Disguised unemployment is typical of Indian farming: more people work on a plot than needed, so removing some would not lower output.","e":"If 8 family members work a farm that needs 5, the 3 extra are disguisedly unemployed.","src":["ASO 20 Aug 2025 S3"]},{"id":"q0328","q":"Which of the following is the feature of the economic system of India?","o":["Goods and services are distributed among people based on their needs and ability to buy.","The Government provides essential goods and services that the market fails to provide.","Only public healthcare facilities are provided to citizens.","Production depends on market forces."],"a":1,"x":"India has a mixed economy: markets decide most production, but the government provides essential goods and services that markets fail to supply, such as public health, schooling and infrastructure.","e":"The 1956 Industrial Policy Resolution set the public–private mix.","src":["ASO 21 Aug 2025 S2"]},{"id":"q0331","q":"The ______ is essentially an adjustment factor used to convert nominal GNP into real GNP.","o":["GDP deflator","GNP deflator","GNP inflator","GDP inflator"],"a":1,"x":"The GNP deflator converts nominal GNP to real GNP: GNP deflator = (Nominal GNP ÷ Real GNP) × 100.","e":"If nominal GNP is ₹120 and real GNP is ₹100, the deflator is 120 — prices rose 20%.","src":["ASO 21 Aug 2025 S2"]},{"id":"q0335","q":"What is the relationship between marginal cost (MC) and average total cost (ATC) when ATC is decreasing?","o":["MC is lesser than ATC.","MC remains equal to ATC.","MC is greater than ATC.","MC will remain unaffected."],"a":0,"x":"When marginal cost is below average total cost, it pulls the average down; so while ATC is falling, MC is less than ATC. MC cuts ATC at ATC's lowest point.","e":"Cricket example: a score below your batting average pulls the average down.","src":["ASO 21 Aug 2025 S2"]},{"id":"q0364","q":"How do economies of scale impact production costs?","o":["Economies of scale refer to the reduction in average total cost as production increases, resulting in increased per-unit costs.","Economies of scale occur when the average variable cost decreases with increased production, leading to lower overall production costs.","Economies of scale indicate a direct proportionality between the average fixed cost and production output.","Economies of scale have no influence on production costs."],"a":1,"x":"Economies of scale mean average cost falls as output grows, as fixed costs are spread over more units and bulk buying and specialisation cut per-unit costs.","e":"A car plant making 1 lakh cars a year has a lower cost per car than one making 1,000.","src":["ASO 21 Aug 2025 S3"]},{"id":"q0366","q":"_____ is a quantitative process of change of scale and size of the economy which can be measured.","o":["Growth","Development","Evolution","Progress"],"a":0,"x":"Growth is a quantitative, measurable rise in output, such as GDP; development is a wider qualitative change including health, education and welfare.","e":"A country can grow without developing if the gains don't reach people.","src":["ASO 21 Aug 2025 S3"]},{"id":"q0374","q":"Worker population ratio is defined as ________.","o":["the percentage of employed persons in the population that is available for work","the percentage of employed persons in the working-age population","the total working people in a country","the percentage of employed persons in a sector"],"a":1,"x":"The worker population ratio is the percentage of employed persons in the population; DSSSB's key frames it against the working-age population.","e":"If 40 of 100 working-age people have jobs, WPR = 40%.","src":["ASO 21 Aug 2025 S3"],"k":"The PLFS (India's labour survey) defines WPR against the whole population in the age group being measured."},{"id":"q0380","q":"At the point of tangency between the short run average total cost and the long run average total cost, the short run marginal cost is _________.","o":["greater than the long run marginal cost","equals the long run marginal cost","less than the long run marginal cost","is far above the long run marginal cost"],"a":1,"x":"Where the short-run average cost curve touches the long-run average cost curve, short-run marginal cost equals long-run marginal cost.","e":"The long-run average cost curve is the 'envelope' of short-run curves.","src":["ASO 21 Aug 2025 S3"]},{"id":"q0405","q":"GDP estimated at current prices and at constant prices is called ____ and ____ respectively.","o":["Real GDP; Nominal GDP","Real GNP; Nominal GNP","Inflation-adjusted GDP; Constant GDP","Nominal GDP; Real GDP"],"a":3,"x":"GDP at current prices is nominal GDP; GDP at constant (base-year) prices is real GDP, which removes the effect of inflation.","e":"India's current base year for GDP is 2011-12.","src":["ASO 22 Aug 2025 S1"]},{"id":"q0417","q":"What is the primary focus of Amartya Sen's 'Capability Approach'?","o":["Availability of resources","Control over production units","Distribution of income and wealth","Individual capabilities and freedoms"],"a":3,"x":"Amartya Sen's capability approach judges well-being by people's capabilities and freedoms — what they are actually able to do and be — not just income or resources.","e":"This idea underlies the Human Development Index and Sen's book 'Development as Freedom' (1999).","src":["ASO 22 Aug 2025 S1"]},{"id":"q0451","q":"Which of the following types of unemployment arises when the economy faces a recession or depression?","o":["Disguised unemployment","Cyclical unemployment","Frictional unemployment","Structural unemployment"],"a":1,"x":"Cyclical unemployment appears when demand falls in a recession or depression, and falls back when the economy recovers.","e":"Frictional: between jobs. Structural: skills don't match jobs. Disguised: more workers than needed.","src":["ASO 27 Aug 2025 S1"]},{"id":"q0457","q":"Which of the following can cause a leftward shift in the supply curve of a given good?","o":["Decrease in the price of other goods","Technological degradation or complexity in technology","Advancement and improvement in technology used in production","Fall in taxes and cost of production"],"a":1,"x":"A leftward (backward) shift of supply happens when production gets harder or costlier: worse technology, higher input costs or higher taxes.","e":"Better technology or lower taxes shift supply to the right.","src":["ASO 27 Aug 2025 S1"]},{"id":"q0526","q":"Which among the following components is added to the Gross Domestic Product to arrive at the Net National Product?","o":["Income from Abroad","Depreciation","Tax payments","Transfer payments"],"a":0,"x":"Net factor income from abroad is added to GDP to get GNP; depreciation is then subtracted to get NNP.","e":"NNP at factor cost is national income.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S2"]},{"id":"q0565","q":"Which among the following identities is incorrect?","o":["GDP = C + I + G + X - M","NNP = GNP - Depreciation","GDP Deflator = Real GDP/Nominal GDP × 100","NNP = NDP + NFIA"],"a":2,"x":"The GDP deflator is Nominal GDP ÷ Real GDP × 100, not Real ÷ Nominal, so that identity is wrong. The others are correct.","e":"Nominal GDP ₹150, real ₹120 → deflator = 125.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S3"]},{"id":"q0567","q":"Which among the following components should be deducted from Gross Domestic Product to get the Net Domestic Product?","o":["Depreciation","Transfer payments","Tax payments","Interest received"],"a":0,"x":"NDP = GDP − depreciation (consumption of fixed capital).","e":"GDP ₹100 crore, depreciation ₹10 crore → NDP ₹90 crore.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S3"]},{"id":"q0689","q":"______________ = GDP (Gross Domestic Product) + NFIA (net factor income from abroad).","o":["Net Domestic Product","Net National Product","Net national expenditure","Gross National Product"],"a":3,"x":"GNP = GDP + NFIA (net factor income from abroad).","e":"If Indians earn more abroad than foreigners earn in India, NFIA is positive and GNP > GDP.","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S1"]},{"id":"q0728","q":"Law of diminishing marginal utility, means the first unit of consumption of a good yields ________________ than the second unit.","o":["more price","less price","more utility","less utility"],"a":2,"x":"By the law of diminishing marginal utility, each extra unit gives less satisfaction, so the first unit gives more utility than the second.","e":"The first glass of water when thirsty is worth more than the fourth.","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S2"]},{"id":"q1744","q":"Personal Disposable income =","o":["Personal Income + Personal tax payments – Non-tax payments","Personal Income + Personal tax payments + Non-tax payments","Personal Income – Personal tax payments – Non-tax payments","Personal Income – Personal tax payments + Non-tax payments"],"a":2,"x":"Personal Disposable Income = Personal Income − Personal tax payments − Non-tax payments (fines, fees).","e":"PDI is what households can spend or save.","src":["Junior Clerk 11 Nov 2021 S1"]},{"id":"q1745","q":"Which of the following statement is correct regarding Consumer Price Index? I. It is one of the ways to measure change of prices in an economy. II. It is generally expressed in percentage terms","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"The Consumer Price Index tracks the change in retail prices of a fixed basket of goods and services; the change is expressed as a percentage.","e":"CPI (Combined) is the RBI's inflation target measure (4% ± 2%).","src":["Junior Clerk 11 Nov 2021 S1"]},{"id":"q1785","q":"The economy in India is ______.","o":["Communist","Mixed","Socialist","Capitalist"],"a":1,"x":"India has a mixed economy, where public and private sectors exist side by side, adopted under the Nehru-era plans.","e":"USSR: socialist; USA: capitalist; India: mixed.","src":["Junior Clerk 11 Nov 2021 S2"]},{"id":"q1786","q":"National Disposable Income =","o":["Net National Product at market prices + Other current transfers from the rest of the world","Net National Product at factor cost + National debt interest","Net National Product at market prices - Other current transfers from the rest of the world","Net National Product at factor cost - National debt interest"],"a":0,"x":"National Disposable Income = Net National Product at market prices + other current transfers from the rest of the world (NCERT Macroeconomics).","e":"NDI measures how much the nation can spend.","src":["Junior Clerk 11 Nov 2021 S2"]},{"id":"q1789","q":"Which of the following statements is correct regarding Balance of Payments? I. Capital Account and Current account are its two primary components of it. II. It is the systematic record of all economic transactions between the residents of a country with the rest of the world.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"The Balance of Payments is a systematic record of all economic transactions between a country's residents and the rest of the world; its two main parts are the current account and the capital account.","e":"Current account = trade + services + transfers.","src":["Junior Clerk 11 Nov 2021 S2"]},{"id":"q1826","q":"______ is the difference between the monetary value of exports and imports of goods in an economy.","o":["Trade deficit","Trade balance","Trade surplus","Fiscal deficit"],"a":1,"x":"The trade balance is the value of exports minus imports of goods; a positive balance is a trade surplus and a negative one a trade deficit.","e":"Trade balance covers goods only; the current account adds services and transfers.","src":["Junior Clerk 11 Nov 2021 S3"]},{"id":"q1827","q":"The ______ records all international purchases and sales of assets such as money, stocks, bonds, etc.","o":["Capital account","Current account","Trade account","Balance account"],"a":0,"x":"The capital account records international purchases and sales of assets such as money, stocks, bonds, loans and FDI.","e":"Current account = goods, services, transfers; capital account = assets.","src":["Junior Clerk 11 Nov 2021 S3"]},{"id":"q1829","q":"Which of the following statement regarding Wholesale Price Index is true? I. It is the price at which goods are traded in bulk. II. In countries like USA it is referred to as Producer Price Index.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"The Wholesale Price Index measures prices at which goods are traded in bulk; in the USA a similar index is called the Producer Price Index.","e":"India's WPI base year is 2011–12.","src":["Junior Clerk 11 Nov 2021 S3"]},{"id":"q1938","q":"In a ______the government decides what goods are to be produced in accordance with the needs of society.","o":["Mixed economy","Capitalist economy","Socialist economy","Macro Economy"],"a":2,"x":"In a socialist (command) economy the government owns the means of production and decides what, how and for whom goods are produced, according to society's needs.","e":"Capitalist: market decides; mixed: both.","src":["Junior Clerk 12 Nov 2021 S1"]},{"id":"q1940","q":"If we deduct depreciation from GNP the measure of aggregate income that we obtain is called _____. I. Net National Product (NNP) II. Gross National Product (GNP)","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":0,"x":"GNP minus depreciation gives Net National Product (NNP).","e":"GNP − depreciation = NNP; NNP at factor cost = National Income.","src":["Junior Clerk 12 Nov 2021 S1"]},{"id":"q1979","q":"With reference to GDP figures, base year is the year whose prices are being used to calculate the ______.","o":["Real GDP","GNP","NNP","Nominal GDP"],"a":0,"x":"Real GDP values output at the prices of a fixed base year, removing the effect of price changes; nominal GDP uses current prices.","e":"India's GDP base year is 2011–12.","src":["Junior Clerk 12 Nov 2021 S2"]},{"id":"q1981","q":"In a closed economy, there are three sources of demand for domestic goods. Which of the following is one of them?","o":["Savings","International expenses","Government spending","Net exports"],"a":2,"x":"In a closed economy demand for domestic goods comes from consumption, investment and government spending; net exports exist only in an open economy.","e":"Closed: C + I + G; open: C + I + G + (X − M).","src":["Junior Clerk 12 Nov 2021 S2"]},{"id":"q1982","q":"Which of the following statement(s) is/are NOT correct about depreciation with reference to accounting? I. It is the cost of the goods divided by number of years of its useful life. II. It is an annual allowance for wear and tear of a capital goods.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":3,"x":"Both statements about depreciation are correct: it is an annual allowance for wear and tear, and in simple accounting it is the cost of the good divided by its years of useful life. So neither is incorrect.","e":"NDP = GDP − depreciation.","src":["Junior Clerk 12 Nov 2021 S2"]},{"id":"q2024","q":"What is the special case of oligopoly where there are exactly two sellers is called?","o":["Duopoly","Monopolistic Competition","Monopoly","Perfect Competition"],"a":0,"x":"A duopoly is an oligopoly with exactly two sellers.","e":"Monopoly: one seller; oligopoly: a few.","src":["Junior Clerk 12 Nov 2021 S3"]},{"id":"q2025","q":"Goods that are of durable character which are used in the production process are called________. I. Consumption goods II. Capital goods","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":1,"x":"Capital goods are durable goods used in production over many years, such as machines, tools and buildings; consumption goods satisfy wants directly.","e":"Capital goods produce other goods.","src":["Junior Clerk 12 Nov 2021 S3"]},{"id":"q2026","q":"Gross National Product (GNP) can be defined as_____.","o":["Gross Domestic Product – Net factor income from abroad","Gross Domestic Product + Net factor income from abroad","Net National Product – Net factor income from abroad","Net National Product + Net factor income from abroad"],"a":1,"x":"GNP = GDP + Net factor income from abroad.","e":"GNP − depreciation = NNP.","src":["Junior Clerk 12 Nov 2021 S3"]},{"id":"q2067","q":"National Income can also be called ______.","o":["Net National Product at factor cost","Net National Product at market cost","Gross national product at factor cost","Gross national product at market cost"],"a":0,"x":"National Income is the Net National Product at factor cost (NNP_FC).","e":"NI = NNP at market prices − net indirect taxes.","src":["Junior Clerk 13 Nov 2021 S1"]},{"id":"q2068","q":"Which of the following statements is correct regarding Monopoly in the market? I. Monopoly firm is a price maker II. There is a single buyer in monopoly","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":0,"x":"A monopoly firm is a price maker because it is the only seller. A single buyer is a monopsony, not a monopoly, so only I is correct.","e":"Monopoly: one seller; monopsony: one buyer.","src":["Junior Clerk 13 Nov 2021 S1"]},{"id":"q2106","q":"The point on the supply curve at which a firm earns normal profit is called the ________________. I. Break-even Point II. Shut Down Point","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":0,"x":"The break-even point is where a firm's price equals average cost, so it earns only normal profit. The shut-down point is where price equals minimum average variable cost.","e":"Break-even = normal profit.","src":["Junior Clerk 13 Nov 2021 S2"]},{"id":"q2147","q":"In which of the following economic societies the goods produced are distributed among people not on the basis of what people need but on the basis of Purchasing Power?","o":["Traditional society","Capitalist society","Socialist society","Mixed economy"],"a":1,"x":"In a capitalist economy goods go to those who can pay (purchasing power), not to those who need them most; in a socialist economy distribution follows need.","e":"Capitalism: market and profit decide.","src":["Junior Clerk 13 Nov 2021 S3"]},{"id":"q2437","q":"A person is a truck-driver who transports goods to various parts of the country. Which economic sector does he belong to?","o":["Primary","Secondary","Tertiary","Quaternary"],"a":2,"x":"A truck driver provides a transport service, so he is in the tertiary (service) sector.","e":"Farmer: primary; factory worker: secondary; driver: tertiary.","src":["Junior Clerk 15 Nov 2021 S2"]},{"id":"q2593","q":"Goods that may be used by other producers as material inputs are called _______.","o":["Intermediate goods","Final goods","Consumer goods","Capital goods"],"a":0,"x":"Intermediate goods are used by other producers as inputs, e.g. steel for cars; they are not counted separately in GDP, to avoid double counting.","e":"Final goods reach the end user.","src":["Junior Clerk 16 Nov 2021 S3","Senior Scientific Assistant (Biology) 18 Sep 2021 S2"]},{"id":"q2594","q":"_______ record the transactions in goods, services and assets between residents of a country with the rest of the world. I. Balance of Payment II. Trade deficit","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":0,"x":"The Balance of Payments records transactions in goods, services and assets between residents of a country and the rest of the world; a trade deficit is only one part of it.","e":"BoP = current account + capital account.","src":["Junior Clerk 16 Nov 2021 S3"]},{"id":"q2663","q":"What is the market structure, where the number of sellers is few, is called?","o":["Oligopoly","Monopoly","Duopoly","Perfect Competition"],"a":0,"x":"An oligopoly is a market with a few sellers; with exactly two it is a duopoly.","e":"Automobiles and telecom are oligopolies.","src":["Junior Clerk 16 Nov 2021 S2"]},{"id":"q1334","q":"Which of the following components is not taken into account while calculating national income by expenditure method?","o":["Household consumption","Investment expenditure","Purchase of shares and bonds","Government expenditure"],"a":2,"x":"The expenditure method adds up household consumption, investment, government spending and net exports. Buying shares and bonds is a transfer of ownership, not new production, so it is excluded.","e":"Also excluded: second-hand goods and transfer payments.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q1339","q":"Complementary goods have a __________ cross price elasticity.","o":["positive","negative","zero","in finite"],"a":1,"x":"Complementary goods (used together) have a negative cross-price elasticity: if one's price rises, demand for the other falls.","e":"Car and petrol are complements; tea and coffee are substitutes (positive).","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q2705","q":"Gross Domestic Product (GDP) + Income from Abroad - Depreciation = _________","o":["Private Transfers","Net Domestic Product","Gross National Product","Net National Product"],"a":3,"x":"GDP + Net factor income from abroad = GNP; GNP − Depreciation = Net National Product (NNP).","e":"","src":["Ahlmad 16 Oct 2021 S1"]},{"id":"q0883","q":"What type of unemployment predominantly affects the agricultural sector in India, especially during off-seasons?","o":["Structural unemployment","Seasonal unemployment","Cyclical unemployment","Frictional unemployment"],"a":1,"x":"Seasonal unemployment hits agriculture when there is no work between sowing and harvesting.","e":"Disguised unemployment is when more people work on a farm than needed.","src":["PRT 16 Feb 2026 S3"]},{"id":"q0918","q":"Which index does the Government of India use to assess the employment situation in the country?","o":["Worker Population Ratio (WPR)","Human Development Index (HDI)","Gini Coefficient","Consumer Price Index (CPI)"],"a":0,"x":"The worker population ratio (WPR), from the Periodic Labour Force Survey, is used to judge India's employment situation, along with the unemployment rate and labour force participation rate.","e":"HDI measures human development; the Gini coefficient measures inequality; CPI measures inflation.","src":["PRT 17 Feb 2026 S3"]},{"id":"q0924","q":"In national income accounting, GNP is the abbreviation used for __________.","o":["Gross Net Product","Gross National Product","General National Policy","Gross Nominal Product"],"a":1,"x":"GNP stands for Gross National Product: GDP plus net factor income from abroad.","e":"GNP = GDP + NFIA.","src":["PRT 18 Feb 2026 S1"]},{"id":"q0955","q":"In the balance of payments of an open economy, what does a current account surplus show?","o":["A country is importing more goods and services than it exports.","It indicates heavy borrowing from abroad.","It indicates less borrowing from abroad.","A country is exporting more goods and services than it imports."],"a":3,"x":"A current account surplus means a country's exports of goods, services and transfers exceed its imports of them.","e":"A deficit (imports > exports) must be financed by capital inflows or reserves.","src":["PRT 18 Feb 2026 S2"]},{"id":"q0964","q":"Which of the following is NOT a rural development measure?","o":["Increase in income level in the industrial sector","Infrastructure development and special measures for poverty","Development of literacy and skill development","Development of productive resources of each locality"],"a":0,"x":"Rural development covers infrastructure, special anti-poverty measures, literacy and skills, and developing each locality's productive resources. Raising incomes in the industrial sector is not part of it.","e":"Rural development = village infrastructure + people + local resources.","src":["PRT 18 Feb 2026 S3"]},{"id":"q0989","q":"What does BPO commonly refer to?","o":["Business Process Outsourcing","Banking Process Order","Basic Product Outsourcing","Business Private Operations"],"a":0,"x":"BPO means Business Process Outsourcing: firms contract out work such as customer support, billing or data entry.","e":"Voice BPOs are call centres; non-voice BPOs handle back-office work.","src":["PRT 19 Feb 2026 S1"]},{"id":"q0994","q":"Which of the following is a key feature of the tertiary sector in advanced economies?","o":["Overproduction of manufactured goods for export","Reliance on large-scale primary industries","Growth of highly specialized and knowledge-based services","Dominance of low-skilled labor"],"a":2,"x":"In advanced economies the tertiary (service) sector dominates, especially highly specialised, knowledge-based services such as IT, finance and research.","e":"Primary → secondary → tertiary as an economy develops.","src":["PRT 19 Feb 2026 S1"]},{"id":"q1024","q":"What causes structural unemployment in the context of India?","o":["Seasonal demand fluctuations","Temporary layoffs during economic slowdowns","Slowdown in the agriculture","Insufficient qualifications to meet job demands due to changes in the economy"],"a":3,"x":"Structural unemployment comes from a mismatch between workers' skills and the jobs available when the economy's structure changes, e.g. technology or new industries.","e":"Seasonal = off-season farm work; cyclical = recessions; frictional = between jobs.","src":["PRT 19 Feb 2026 S3"]},{"id":"q1076","q":"At the time of Independence, how was India's population primarily dependent on agriculture?","o":["A large majority of the population depended on agriculture.","Only the urban population depended on agriculture.","A small minority of the population depended on agriculture.","About half of the population depended on agriculture."],"a":0,"x":"At Independence about 70–75% of India's workforce depended on agriculture, which was largely stagnant and low in productivity.","e":"Agriculture still employs about 45% of India's workforce.","src":["PRT 23 Feb 2026 S2"]},{"id":"q1095","q":"Why is human capital important for economic growth?","o":["It drives innovation and productivity","It boosts food production","It reduces foreign aid","It increases population growth"],"a":0,"x":"Human capital — people's education, skills and health — drives innovation and productivity, which are the base of long-run growth.","e":"Spending on schools and hospitals is called investment in human capital.","src":["PRT 23 Feb 2026 S3"]},{"id":"q1138","q":"A commodity becomes a final good when: (A) it passes out of the economic flow; (B) it becomes ready for the next process. Select the correct option.","o":["Both (A) and (B) are correct","Only (B) is correct","Both (A) and (B) are INCORRECT","Only (A) is correct"],"a":3,"x":"A final good has passed out of the production flow to its end user; it needs no further processing. A good 'ready for the next process' is intermediate. So only A is correct.","e":"Bread bought by a household is final; flour bought by a bakery is intermediate.","src":["PRT 26 Mar 2026 S2"]},{"id":"q1165","q":"Which of the following does the National Income Accounting Identity represent?","o":["It represents the equality between total expenditures and total income in an economy.","It represents the proportion of national income allocated to different sectors of the economy.","It represents the difference between disposable income and personal savings.","It represents the relationship between Gross National Product (GNP) and Gross Domestic Product (GDP)."],"a":0,"x":"The national income accounting identity says that in an economy total expenditure (output) equals total income, so GDP can be measured by the output, income or expenditure method.","e":"Y = C + I + G + (X − M).","src":["PRT 26 Mar 2026 S3"]},{"id":"q1177","q":"What were the recommended national poverty lines for rural and urban areas by the Tendulkar Committee for 2011-12?","o":["₹1,000 per capita per month for rural areas and ₹1,200 per capita per month for urban areas","₹816 per capita per month for rural areas and ₹1,000 per capita per month for urban areas","₹500 per capita per month for rural areas and ₹700 per capita per month for urban areas","₹700 per capita per month for rural areas and ₹800 per capita per month for urban areas"],"a":1,"x":"The Tendulkar methodology gave 2011-12 poverty lines of ₹816 per person per month in rural areas and ₹1,000 in urban areas (about ₹27 and ₹33 a day), putting poverty at 21.9%.","e":"The Rangarajan Committee (2014) later suggested ₹972 rural and ₹1,407 urban.","src":["PRT 31 Mar 2026 S1"]},{"id":"q1184","q":"Which of the following is NOT included in the calculation of Gross Domestic Product (GDP)?","o":["Net exports","Sale or purchase of second-hand goods","Government purchases of goods and services","T ransfer payments from the government"],"a":3,"x":"GDP counts only the value of final goods and services produced in the year. Transfer payments (pensions, subsidies, scholarships) are only redistributions, not production, so they are excluded.","e":"GDP = C + I + G + (X − M).","src":["PRT 31 Mar 2026 S1"],"k":"Sales of second-hand goods (option B) are also excluded from GDP, since they were counted when first produced; DSSSB's key is D."},{"id":"q1191","q":"What is the primary difference between closed and open economies?","o":["International trade","Domestic production","Government intervention","Consumer preferences"],"a":0,"x":"A closed economy has no trade with other countries; an open economy trades goods, services and capital internationally.","e":"Open economy: GDP = C + I + G + (X − M).","src":["PRT 31 Mar 2026 S1"]},{"id":"q1219","q":"Which of the following is a part of urban infrastructure?","o":["Cattle shed","Multi-storey parking","Grain storage on a farm","Ploughing tools"],"a":1,"x":"Multi-storey parking is urban infrastructure. A cattle shed, farm grain store and ploughing tools are rural or agricultural assets.","e":"Urban infrastructure also includes metro rail, sewerage and flyovers.","src":["PRT 31 Mar 2026 S3"]},{"id":"q1230","q":"What does a high HDI value usually indicate for a country?","o":["Limited access to health services and education","High income inequality and poverty","High levels of human development","Low life expectancy and educational attainment"],"a":2,"x":"A high HDI value (close to 1) means a high level of human development: long life expectancy, good schooling and decent income.","e":"UNDP groups countries as very high, high, medium or low HDI.","src":["PRT 31 Mar 2026 S3"]},{"id":"q1240","q":"A capital budgeting decision is a ___________ investment decision.","o":["Fortnightly","One-month","Monthly","Long-term"],"a":3,"x":"Capital budgeting decides on long-term investments such as buying machinery or setting up a plant, whose benefits come over many years.","e":"Working capital decisions are short-term.","src":["PRT 3 Apr 2026 S2"]},{"id":"q1249","q":"Which of the following is NOT a characteristic of tertiary activities?","o":["They provide services to the primary and secondary sectors","They include banking and IT services","They include transport, trade and communication","Direct extraction of materials from the earth"],"a":3,"x":"Tertiary activities provide services (transport, trade, communication, banking, IT) to the primary and secondary sectors; direct extraction of materials from the earth is a primary activity.","e":"Primary = extract; secondary = make; tertiary = serve.","src":["PRT 3 Apr 2026 S2"]},{"id":"q1252","q":"What is the full form of FDI?","o":["Foreign Domestic Investment","Foreign Direct Investment","Foreign Direct Interest","Foreign Domestic Interest"],"a":1,"x":"FDI stands for Foreign Direct Investment: a foreign investor takes a lasting stake (10% or more) in a business in another country.","e":"FPI (Foreign Portfolio Investment) is a smaller stake in shares or bonds.","src":["PRT 3 Apr 2026 S2"]},{"id":"q1267","q":"When did the NITI Aayog launch the baseline edition of the Multidimensional Poverty Index for India?","o":["2022","2025","2023","2021"],"a":3,"x":"NITI Aayog released India's baseline National Multidimensional Poverty Index in 2021, based on NFHS-4 (2015–16) data.","e":"It measures health, education and standard of living with 12 indicators.","src":["PRT 10 Apr 2026 S1"]},{"id":"q1280","q":"Structural unemployment is mainly caused by __________.","o":["Cyclical fall in demand","Seasonal variation","Skill mismatch","Voluntary quitting"],"a":2,"x":"Structural unemployment comes mainly from a skill mismatch: workers' skills don't fit the jobs available as the economy changes.","e":"A typist displaced by computers is structurally unemployed until retrained.","src":["PRT 10 Apr 2026 S2"]},{"id":"q1401","q":"The formula for calculating Net National Product (NNP) is ______.","o":["GNP – Depreciation","GDP + Depreciation","GNP + Depreciation","GDP – Depreciation"],"a":0,"x":"NNP = GNP − depreciation.","e":"NNP at factor cost is national income.","src":["TGT 24 Jun 2023 S3"]},{"id":"q1437","q":"As per the Handbook of Statistics on the Indian Economy, 2019-20, published by the RBI, which state has the highest GDP?","o":["Tamil Nadu","Maharashtra","Karnataka","Gujarat"],"a":1,"x":"Maharashtra has the largest state GDP (GSDP) in India, according to the RBI's Handbook of Statistics.","e":"Maharashtra's capital, Mumbai, is India's financial hub.","src":["TGT 25 Jun 2023 S2"]},{"id":"q1486","q":"If the general price level increases, the purchasing power of money:","o":["Increases","Doubles","Decreases","Stays the same"],"a":2,"x":"When the general price level rises (inflation), each rupee buys fewer goods, so money's purchasing power falls.","e":"At 10% inflation, ₹100 buys what about ₹91 bought a year earlier.","src":["TGT 29 Aug 2025"]},{"id":"q1496","q":"Which of the following statements are correct? 1. Workers that are engaged by someone or an enterprise and are paid their wages on a regular basis are called regular salaried employees. 2. Workers who own and operate an enterprise to earn their livelihood are called self- employed. 3. Construction workers are called casual wage labourers.","o":["Only 2 and 3","1, 2 and 3","Only 1 and 3","Only 1 and 2"],"a":1,"x":"All three are right: regular salaried employees get wages regularly; self-employed people own and run their own enterprise; construction workers are typically casual wage labourers.","e":"In India most workers are self-employed.","src":["TGT 29 Aug 2025"]},{"id":"q1505","q":"In the context of production theory, what does the term 'marginal rate of technical substitution' (MRTS) measure?","o":["The rate at which total cost increases as output expands","The rate at which marginal cost decreases with an increase in output","The rate at which a firm can substitute between two inputs while keeping output constant","The rate at which average variable cost varies with changes in fixed inputs"],"a":2,"x":"The marginal rate of technical substitution (MRTS) is how much of one input (say capital) a firm can give up for one more unit of another (labour) while keeping output the same.","e":"It is the slope of an isoquant.","src":["TGT 24 Aug 2025 S1"]},{"id":"q1522","q":"The sum total of aggregate factor payments in an economy, the national income, is equal to the aggregate value of the output of final goods, the _____.","o":["net income","gross domestic product","equilibrium income","aggregate demand"],"a":1,"x":"National income equals total factor payments, which in turn equals the value of all final goods and services produced — the gross domestic product.","e":"The circular flow: output = income = expenditure.","src":["TGT 24 Aug 2025 S1"]},{"id":"q1541","q":"In income distribution, what does the Lorenz curve measure?","o":["The degree of income inequality in a society","The total income generated in a country's economy","The concentration of wealth among the richest individuals","The share of income earned by different quintiles of the population"],"a":0,"x":"The Lorenz curve shows the degree of income inequality: the further it bows below the line of equality, the more unequal the society.","e":"The Gini coefficient is calculated from the Lorenz curve.","src":["TGT 24 Aug 2025 S3"]},{"id":"q1550","q":"Which of the following states has a higher proportion of population which is multi- dimensionally poor?","o":["Kerala","Bihar","Gujarat","Maharashtra"],"a":1,"x":"Bihar has the highest share of multidimensionally poor people in NITI Aayog's Multidimensional Poverty Index; Kerala has the lowest.","e":"The MPI uses three dimensions: health, education and standard of living.","src":["TGT 31 Aug 2025 S1"]},{"id":"q0775","q":"In NITI Aayog's SDG India Index, which pairs of category and index score are correctly matched? 1. Aspirant: 0–49  2. Performer: 50–64  3. Front Runner: 65–99  4. Achiever: 100","o":["Only 2","1, 2, 3 and 4","Only 1 and 3","Only 3 and 4"],"a":1,"x":"All four pairs are correct: in NITI Aayog's SDG India Index, Aspirant = 0–49, Performer = 50–64, Front Runner = 65–99, Achiever = 100.","e":"The SDG India Index was first released in 2018.","src":["PGT 25 Sep 2025"]},{"id":"q0797","q":"The consumption per unit of income is known as:","o":["marginal propensity to save (MPS)","marginal propensity to consume (MPC)","average propensity to save (APS)","average propensity to consume (APC)"],"a":3,"x":"Average propensity to consume (APC) = total consumption ÷ total income, the consumption per unit of income.","e":"Income ₹100, consumption ₹80 → APC = 0.8, APS = 0.2 (APC + APS = 1).","src":["PGT 11 Jul 2025 S1"]},{"id":"q0808","q":"What does GEM refer to in context of human development?","o":["Global Economic Measurement","Gender Equality Monitor","Gender Empowered Measurement","General Education Metric"],"a":2,"x":"GEM is the Gender Empowerment Measure, introduced by UNDP in 1995 to measure women's share in political and economic decision-making.","e":"It was replaced by the Gender Inequality Index (GII) in 2010.","src":["PGT 22 Sep 2025"]},{"id":"q0830","q":"Which sector is the backbone of the Indian economy?","o":["Agriculture","Services","Information Technology","Manufacturing"],"a":0,"x":"Agriculture is called the backbone of the Indian economy because it employs the largest share of workers (about 45%) and supports rural livelihoods.","e":"Services contribute the largest share of GDP.","src":["PGT 26 Sep 2025"]},{"id":"q0844","q":"Which of the following accurately describes 'fixed costs' in production?","o":["Costs that include both explicit and implicit expenses","Costs that remain constant regardless of the level of production output","Costs that fluctuate based on market conditions","Costs that vary with the level of production output"],"a":1,"x":"Fixed costs stay the same whatever the output: rent, salaries of permanent staff, insurance. Variable costs change with output.","e":"A factory's rent is fixed; the raw material it uses is variable.","src":["PGT 14 Jul 2025"]},{"id":"q0845","q":"Select the INCORRECT option. Social infrastructure improves human productivity and efficiency through facilities for:","o":["energy","education","housing","health"],"a":0,"x":"Social infrastructure means education, health and housing, which improve human productivity. Energy is economic infrastructure.","e":"Economic infrastructure: power, transport, communication, banking.","src":["PGT 14 Jul 2025"]}]},{"id":"money","n":"Money, Banking and the RBI","qs":[{"id":"q0016","q":"In which year were Regional Rural Banks set up in India?","o":["1972","1975","1974","1971"],"a":1,"x":"Regional Rural Banks were set up on 2 October 1975 on the advice of the Narasimham Working Group. Prathama Bank, Moradabad (UP), was the first.","e":"RRB share capital: Centre 50%, sponsor bank 35%, state government 15%.","src":["ASO 18 Aug 2025 S1"]},{"id":"q0124","q":"Suppose a bank has ₹10,000 crore as deposits and the CRR is 15%. What amount should the bank maintain in the form of cash holdings with it?","o":["₹1,500 crore","₹9,900 crore","₹9,000 crore","₹8,500 crore"],"a":0,"x":"CRR is the share of deposits a bank must keep with the RBI as cash. 15% of ₹10,000 crore = ₹1,500 crore.","e":"SLR is different: that share is kept in liquid assets such as government securities.","src":["ASO 19 Aug 2025 S2"]},{"id":"q0127","q":"Which of the following statements is FALSE regarding REPO Rate of RBI?","o":["Repo rate is also known as Repurchase Agreement or Repurchase Option.","The repo rate is changed by the Monetary Policy Committee (MPC) of RBI.","Repo rate is the rate at which commercial bank deposits to RBI.","The current Repo rate in India is fixed by RBI at 6% since 9 th April 2025."],"a":2,"x":"Repo rate is the rate at which the RBI LENDS to commercial banks against securities; the rate at which the RBI BORROWS from banks is the reverse repo rate.","e":"Repo = RBI lends; reverse repo = RBI borrows.","src":["ASO 19 Aug 2025 S2"],"k":"Option D was true when the question was set (repo fixed at 6% on 9 April 2025); the rate was cut to 5.50% in June 2025."},{"id":"q0176","q":"How do you calculate the spread interest rate?","o":["Lending rate plus deposit rate","Lending rate minus deposit rate","Bank rate minus repo rate","Bank rate plus repo rate"],"a":1,"x":"Spread (net interest margin) = lending rate minus deposit rate; it is the bank's main source of profit.","e":"Lend at 10% and pay 6% on deposits: the spread is 4%.","src":["ASO 19 Aug 2025 S3"]},{"id":"q0177","q":"Which of the following is a challenge faced by MFIs in India?","o":["High repayment rates of loans","Over-regulation by international financial bodies","Lack of interest from rural populations","Over-indebtedness of clients"],"a":3,"x":"Over-indebtedness is a major MFI problem: poor borrowers take several loans from different lenders and then cannot repay.","e":"The 2010 Andhra Pradesh microfinance crisis was driven by over-indebtedness.","src":["ASO 19 Aug 2025 S3"]},{"id":"q0205","q":"What is a cheque?","o":["A type of digital currency","A written instruction to a bank to pay money","A loan agreement with a bank","A form of direct cash payment"],"a":1,"x":"A cheque is a written, signed order from an account holder telling the bank to pay a stated sum to a named person or the bearer.","e":"A demand draft is issued by the bank itself, so it cannot bounce.","src":["ASO 20 Aug 2025 S1"]},{"id":"q0211","q":"What is the primary role of Self-Help Groups (SHGs) in rural development?","o":["They promote collective savings and access to microfinance.","They provide rural households with subsidised government loans.","They act as informal money lenders in villages.","They serve as rural government employment offices."],"a":0,"x":"Self-Help Groups, usually 10–20 rural women, pool small savings and give members loans, which helps them get microfinance and bank credit.","e":"NABARD's SHG–Bank Linkage Programme began in 1992.","src":["ASO 20 Aug 2025 S1"]},{"id":"q0216","q":"Identify the correct statement(s) from the following in the context of Cash Reserve Ratio. i. Central banks adopt this method to control credit. ii. The first time it was adopted by the Federal Reserve System of the USA. iii. It does not apply to non-banking financial intermediaries.","o":["Only i","Only ii","Only i and iii","All, i, ii and iii"],"a":2,"x":"Statement i is true: CRR is a quantitative credit-control tool. Statement iii is true: CRR applies to banks, not NBFCs. DSSSB's key treats statement ii as false.","e":"Cutting CRR releases money for banks to lend; raising it pulls money out of the system.","src":["ASO 20 Aug 2025 S1"],"k":"Many Indian textbooks say the variable reserve ratio was first used by the US Federal Reserve (1930s), which would make ii true too. DSSSB's key marks 'only i and iii'."},{"id":"q0254","q":"Which institution(s) has/have the sole right to issue currency notes in India?","o":["Reserve Bank of India","Ministry of Finance","Stock exchanges","Commercial banks"],"a":0,"x":"The RBI has the sole right to issue banknotes in India under Section 22 of the RBI Act, 1934.","e":"The ₹1 note and all coins are issued by the Government of India (Ministry of Finance).","src":["ASO 20 Aug 2025 S2"]},{"id":"q0285","q":"Which of the following banks has the tagline ‘One Family One Bank’?","o":["Central Bank of India","Bank of India","Canara Bank","Bank of Maharashtra"],"a":3,"x":"'One Family One Bank' is the tagline of Bank of Maharashtra, headquartered in Pune.","e":"SBI: 'The Banker to Every Indian'.","src":["ASO 20 Aug 2025 S3"]},{"id":"q0300","q":"What is the primary objective of Microfinance Institutions (MFIs) in India?","o":["Providing only insurance services","Investing in stock markets and mutual funds","Lending to large companies at high interest rates","Providing financial services to people who are underserved or excluded from banking"],"a":3,"x":"Microfinance institutions give small loans, savings and insurance to low-income people who are underserved or left out by banks.","e":"Muhammad Yunus's Grameen Bank (Bangladesh) pioneered microcredit.","src":["ASO 20 Aug 2025 S3"]},{"id":"q0455","q":"What is the primary regulatory body for microfinance institutions in India?","o":["Securities and Exchange Board of India (SEBI)","National Bank for Agriculture and Rural Development (NABARD)","Reserve Bank of India (RBI)","State Bank of India (SBI)"],"a":2,"x":"The RBI regulates NBFC-MFIs (microfinance institutions); it has set rules on interest rates and household income limits.","e":"NABARD promotes SHG–bank linkage but is not the MFI regulator.","src":["ASO 27 Aug 2025 S1"]},{"id":"q1572","q":"Where is the headquarters of Bandhan Financial Services Limited located?","o":["Surat","Hyderabad","Mumbai","Kolkata"],"a":3,"x":"Bandhan Financial Services and Bandhan Bank are headquartered in Kolkata; Bandhan started as a microfinance NGO in 2001 and became a universal bank in 2015.","e":"IDFC First Bank also got a universal bank licence in 2014-15.","src":["Patwari 17 Sep 2022 S3"]},{"id":"q1610","q":"Which type of financial institution serves a specific demographic per their field of membership, such as teachers or members of the military?","o":["Credit Unions","Retail Banks","Commercial banks","Investment Banks and Companies"],"a":0,"x":"Credit unions are member-owned financial cooperatives whose members share a common bond, such as the same profession (teachers) or organisation (military).","e":"In India, cooperative credit societies play a similar role.","src":["Patwari 20 Aug 2022 S1"]},{"id":"q0485","q":"Which among the following is defined as the minimum interest rate of a bank below which it cannot lend, except in some cases allowed by the RBI?","o":["Base rate","Repo rate","Reverse repo rate","Call money rate"],"a":0,"x":"The base rate was the minimum rate below which banks could not lend, except in cases allowed by the RBI; it began in July 2010.","e":"From April 2016 the MCLR replaced it for new loans.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S1"]},{"id":"q0486","q":"Which among the following banks sponsored the first regional rural bank in India by name Prathama Bank?","o":["Punjab National Bank","Syndicate Bank","Bank of India","State Bank of India"],"a":1,"x":"Prathama Bank, India's first Regional Rural Bank (Moradabad, 2 October 1975), was sponsored by Syndicate Bank.","e":"Syndicate Bank merged into Canara Bank in 2020.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S1"]},{"id":"q0487","q":"Which among the following is not a method adopted by RBI to maintain the liquidity of economy?","o":["Buying of government bonds","Maintaining cash reserve ratio","Buying of shares","Decreasing repo rate"],"a":2,"x":"The RBI manages liquidity with CRR, repo and reverse repo rates and open market operations (buying and selling government securities). Buying company shares is not one of its tools.","e":"Buying bonds injects liquidity; selling bonds absorbs it.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S1"]},{"id":"q0488","q":"Which among the following banks is authorised for providing credit for the development of agriculture?","o":["NABARD","RBI","SBI","SIDBI"],"a":0,"x":"NABARD (1982) is the apex bank for agricultural and rural credit, refinancing banks that lend to agriculture.","e":"SIDBI (1990) serves small industries.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S1"]},{"id":"q0525","q":"Which among the following banks is not a public sector bank?","o":["United Bank of India","Central Bank of India","Lakshmi Vilas Bank","Syndicate Bank"],"a":2,"x":"Lakshmi Vilas Bank was a private-sector bank; it was merged into DBS Bank India in November 2020.","e":"United Bank of India and Syndicate Bank were public sector banks, merged into PNB and Canara Bank in April 2020.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S2"]},{"id":"q0527","q":"When was the Small Industries Development Bank of India established?","o":["1995","1984","1998","1990"],"a":3,"x":"The Small Industries Development Bank of India was set up on 2 April 1990, under an Act of Parliament, as the apex bank for MSMEs; it is headquartered in Lucknow.","e":"Other apex banks: EXIM Bank (1982), NABARD (1982), NHB (1988).","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S2"]},{"id":"q0566","q":"Apart from the Oriental bank of Commerce, which of the following banks were merged with Punjab National Bank in April 2020?","o":["Corporation Bank","Andhra Bank","United Bank of India","Canara Bank"],"a":2,"x":"From 1 April 2020, Oriental Bank of Commerce and United Bank of India were merged into Punjab National Bank.","e":"Same day: Syndicate → Canara Bank; Allahabad → Indian Bank; Andhra and Corporation → Union Bank of India.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S3"]},{"id":"q0606","q":"Which among the following banks was not nationalised in 1969?","o":["Allahabad Bank","Central Bank of India","Bank of India","Andhra Bank"],"a":3,"x":"Andhra Bank was not among the 14 banks nationalised in July 1969; it was nationalised in the second round in April 1980.","e":"1969 nationalisation was under Indira Gandhi (banks with deposits over ₹50 crore).","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S2","PGT 30 Jun 2021 S1"]},{"id":"q0608","q":"Which among the following banks was earlier known as the 'Imperial Bank of India'?","o":["State Bank of India","Bank of India","Reserve Bank of India","Central Bank of India"],"a":0,"x":"The State Bank of India was formerly the Imperial Bank of India (1921), which was nationalised as SBI on 1 July 1955 on the Gorwala Committee's advice.","e":"The Imperial Bank was formed by merging the Presidency Banks of Bengal, Bombay and Madras.","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S2"]},{"id":"q0645","q":"Which among the following institutions acts as the ‘lender of the last resort' in India?","o":["Reserve Bank of India","State Bank of India","National Bank for Agriculture and Rural Development","Central Bank of India"],"a":0,"x":"The RBI is the lender of last resort: it lends to banks in a crisis when no one else will, protecting depositors and the system.","e":"Other RBI roles: banker to the government, banker's bank, custodian of foreign exchange.","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S3"]},{"id":"q0649","q":"Which among the following is the rate at which short term funds are borrowed and lent in the money market?","o":["Bank rate","Repo rate","Reverse Repo rate","Call money rate"],"a":3,"x":"The call money rate is the interest rate on very short-term (overnight) borrowing and lending between banks in the money market.","e":"'Notice money' is for 2 to 14 days; 'term money' for longer.","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S3"]},{"id":"q0685","q":"Which of the following banks primarily focuses on the development of MSME (Micro, Small and Medium Enterprise) sector?","o":["State Bank of India","Small Industries Development Bank of India","National Bank For Agriculture & Rural Development","Reserve Bank of India"],"a":1,"x":"SIDBI (1990, headquartered in Lucknow) is the principal development bank for MSMEs.","e":"NABARD serves agriculture and rural development; EXIM Bank serves exporters.","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S1"]},{"id":"q0687","q":"When was Export-Import Bank of India established?","o":["1975","1970","1996","1982"],"a":3,"x":"The Export-Import (EXIM) Bank of India was set up on 1 January 1982 to finance and promote India's international trade; its headquarters is Mumbai.","e":"NABARD was also set up in 1982.","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S1"]},{"id":"q0727","q":"Amongst the following, the market value of share is described by ___________.","o":["IPO value of the share","buying or selling value of share","book value of share","future values of all earnings on the share"],"a":1,"x":"A share's market value is the price at which it is currently bought and sold on the stock exchange; it changes with demand and supply.","e":"Face value is fixed at issue (for example ₹10); book value is net assets per share.","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S2"]},{"id":"q1743","q":"Which of the following is an instrument of monetary policy of Reserve Bank of India? I. Repo Rate II. Currency Deposit Ratio III. Liquidity Adjustment Facility","o":["Only II","I and III","II and III","I, II and III"],"a":1,"x":"The Repo Rate and the Liquidity Adjustment Facility are RBI monetary-policy tools. The currency–deposit ratio depends on how much cash the public holds, so it is not an RBI instrument.","e":"RBI tools: repo, reverse repo, CRR, SLR, OMO, LAF, MSF.","src":["Junior Clerk 11 Nov 2021 S1"]},{"id":"q1788","q":"What is the total liability of the monetary authority of India, Reserve Bank of India is called? I. Monetary Base II. High powered money","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"The RBI's total liability, currency held by the public plus bank reserves with the RBI, is called the monetary base or high-powered money (M0).","e":"M0 = high-powered money; M3 = broad money.","src":["Junior Clerk 11 Nov 2021 S2"]},{"id":"q1828","q":"When banks hold a part of the money people keep in their bank deposits as reserve money and loan out the rest to various investment projects, then it is called ______.","o":["Cash reserve ratio","Currency deposit ratio","Reserve deposit ratio","Statutory liquidity ratio"],"a":2,"x":"The share of deposits banks keep as reserves (lending out the rest) is the reserve–deposit ratio (NCERT Macroeconomics).","e":"The RBI's minimum requirement is set through CRR and SLR.","src":["Junior Clerk 11 Nov 2021 S3"]},{"id":"q1830","q":"Which of the following statement regarding monetary policy of India is correct? I. The primary objective of monetary policy is to maintain price stability while keeping in mind the objective of growth. II. Repo rate is one of the instruments of monetary policy.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"The RBI's monetary policy aims mainly at price stability while keeping growth in mind, and the repo rate is its main policy instrument.","e":"Monetary Policy Committee: 6 members, set up 2016.","src":["Junior Clerk 11 Nov 2021 S3"]},{"id":"q1939","q":"The responsibility of RBI to conduct monetary policy is explicitly mandated under the_____.","o":["Reserve Bank of India Act, 1935","Reserve Bank of India Act, 1934","Reserve Bank of India Act, 1947","Reserve Bank of India Act, 1945"],"a":1,"x":"The RBI's duty to conduct monetary policy is written into the Reserve Bank of India Act, 1934, amended in 2016 to set inflation targeting and the Monetary Policy Committee.","e":"RBI started work on 1 April 1935 under the 1934 Act.","src":["Junior Clerk 12 Nov 2021 S1"]},{"id":"q1942","q":"Which of the following statement(s) is/are true about the Bank Rate? I. It is the rate at which the Reserve Bank is ready to sell or discount bills of exchange. II. This rate has been aligned to the Marginal Standing Facility (MSF) rate.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":1,"x":"Bank Rate is the rate at which the RBI buys or rediscounts bills of exchange (not sells them); it is now aligned to the Marginal Standing Facility rate. So only II is correct.","e":"MSF was introduced in 2011.","src":["Junior Clerk 12 Nov 2021 S1"]},{"id":"q1983","q":"Which of the following statement(s) is/are NOT correct regarding Open Market Operations? I. RBI purchases or sells government securities to the general public in a bid to increase (or decrease) the stock of high powered money in the economy. II. When RBI buys a Government bond in the open market, it pays for it by giving a cheque.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":3,"x":"Both statements are correct: in open market operations the RBI buys or sells government securities to change the stock of high-powered money, and when it buys a bond it pays by cheque, creating new money. So neither is incorrect.","e":"RBI buys securities → money supply rises.","src":["Junior Clerk 12 Nov 2021 S2"]},{"id":"q2027","q":"Which of the following statement(s) is/are true regarding Marginal Standing Facility (MSF)? I. Bank rate has been aligned to the MSF rate and changes automatically. II. Repo rate changes when MSF rate changes.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"The Bank Rate is aligned to the Marginal Standing Facility rate, and the MSF is fixed at the repo rate plus 0.25%, so all three move together.","e":"MSF = repo + 25 basis points.","src":["Junior Clerk 12 Nov 2021 S3"],"k":"MSF is pegged to the repo rate, so strictly it is the MSF that changes when the repo rate changes, not the other way round; DSSSB counts both statements as true."},{"id":"q2028","q":"Which of the following is/are the correct measurement of Assets, with respect to money creation by banking system? I. Reserves + Loans II. Reserves","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":0,"x":"In the money-creation model, a bank's assets are its reserves plus the loans it has made (NCERT Macroeconomics).","e":"Liabilities = deposits; assets = reserves + loans.","src":["Junior Clerk 12 Nov 2021 S3"]},{"id":"q2042","q":"Where is the head office of National Bank for Agriculture and Rural Development (NABARD) located?","o":["Kolkata","Mumbai","New Delhi","Bangalore"],"a":1,"x":"NABARD (set up 1982) is headquartered in Mumbai.","e":"RBI, SEBI and NABARD are all in Mumbai.","src":["Junior Clerk 12 Nov 2021 S3"]},{"id":"q2069","q":"What is the size of the 20 rupees note of the Mahatma Gandhi (new) series?","o":["63 mm x 129 mm","65mm x 140mm","63mm x 120mm","66mm x 129mm"],"a":0,"x":"The ₹20 note of the Mahatma Gandhi (New) series measures 63 mm × 129 mm.","e":"The new ₹20 note is greenish-yellow with the Ellora caves motif.","src":["Junior Clerk 13 Nov 2021 S1"]},{"id":"q2071","q":"What is the difference between the borrowing rate and the lending rate in commercial banks is called?","o":["Float","Loss","Profit","Spread"],"a":3,"x":"A bank's 'spread' is the difference between its lending rate and borrowing (deposit) rate; it is the bank's main source of income.","e":"Net interest margin is the related ratio.","src":["Junior Clerk 13 Nov 2021 S1"]},{"id":"q2105","q":"Which of the following statements is true about Reserve Bank of India? I. The supply of money is regulated by the Reserve Bank of India. II. It acts as a banker to the Government of India.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"The RBI regulates the money supply and acts as banker to the Government of India (and to the states).","e":"RBI roles: issuer of currency, banker's bank, government's banker.","src":["Junior Clerk 13 Nov 2021 S2"]},{"id":"q2107","q":"What is the size of the Rs 2000 Mahatma Gandhi (New) Series note?","o":["69 mm x 169 mm","69 mm x 166 mm","66 mm x 166 mm","66 mm x 169 mm"],"a":2,"x":"The ₹2000 note of the Mahatma Gandhi (New) series measures 66 mm × 166 mm; the RBI began withdrawing it in 2023.","e":"Its back shows the Mangalyaan motif.","src":["Junior Clerk 13 Nov 2021 S2"]},{"id":"q2108","q":"Which of the following statement is correct regarding the Flexible exchange rates system? I. This exchange rate is determined by the forces of market demand and supply. II. It is also known as pegged exchange rate system.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":0,"x":"A flexible (floating) exchange rate is set by market demand and supply. A pegged rate is a fixed rate, so II is wrong.","e":"India follows a managed float.","src":["Junior Clerk 13 Nov 2021 S2"]},{"id":"q2148","q":"Which of the following committee had recommended the formation of payments banks in India?","o":["Bimal Jalan Committee","Nachiket Mor Committee","Subramanian Committee","Narasimham Committee II"],"a":1,"x":"The Nachiket Mor Committee (2013) on financial inclusion recommended payments banks; the RBI licensed them in 2015.","e":"Payments banks can take deposits up to ₹2 lakh but cannot lend.","src":["Junior Clerk 13 Nov 2021 S3"]},{"id":"q2393","q":"Which of the following bank was started in 1865 and had its headquarters in Kolkata?","o":["Dena Bank","Indian Overseas Bank","Allahabad Bank","State Bank of India"],"a":2,"x":"Allahabad Bank, founded in 1865 at Allahabad and later headquartered in Kolkata, was one of India's oldest joint-stock banks; it merged into Indian Bank in 2020.","e":"The oldest existing bank today is the State Bank of India lineage (1806).","src":["Junior Clerk 15 Nov 2021 S1"]},{"id":"q2394","q":"As per the merger of Indian banks on 1 April 2020, with which bank was the Syndicate Bank merged into?","o":["Oriental Bank of Commerce","United Bank of India","Bank of India","Canara Bank"],"a":3,"x":"In the April 2020 bank mergers Syndicate Bank merged into Canara Bank. Oriental Bank of Commerce and United Bank of India went into Punjab National Bank; Andhra and Corporation Banks into Union Bank.","e":"12 public sector banks remain after the mergers.","src":["Junior Clerk 15 Nov 2021 S1"]},{"id":"q2436","q":"Which of the following has not been developed by the National Payments Corporation of India (NPCI)?","o":["UPI","RuPay","IMPS","PhonePe"],"a":3,"x":"UPI, RuPay and IMPS were developed by the National Payments Corporation of India (NPCI); PhonePe is a private payment app that runs on UPI.","e":"NPCI was set up in 2008 by the RBI and the Indian Banks' Association.","src":["Junior Clerk 15 Nov 2021 S2"]},{"id":"q2438","q":"After the merger of 10 Public Sector Banks on April 1, 2020, how many PSBs are there in India?","o":["27","18","12","10"],"a":2,"x":"After the April 2020 merger of 10 public sector banks into 4, India has 12 public sector banks.","e":"Down from 27 in 2017.","src":["Junior Clerk 15 Nov 2021 S2"]},{"id":"q2481","q":"From which year was the Unified Payments Interface (UPI) launched by National Payments Corporation of India (NPCI)?","o":["2014","2015","2016","2017"],"a":2,"x":"NPCI launched the Unified Payments Interface (UPI) in 2016, with the RBI.","e":"NPCI also runs RuPay, IMPS and AEPS.","src":["Junior Clerk 15 Nov 2021 S3"]},{"id":"q2482","q":"Which of the following actions cannot be done by an Aadhaar Enabled Payment System (AEPS)?","o":["Cash Withdrawal","Cash Deposit","Balance Enquiry","Buying on credit"],"a":3,"x":"The Aadhaar Enabled Payment System lets people withdraw or deposit cash and check balances with Aadhaar and a fingerprint; it cannot be used to buy on credit.","e":"AEPS works through banking correspondents (micro-ATMs).","src":["Junior Clerk 15 Nov 2021 S3"]},{"id":"q2592","q":"Which of the following is/are the policy instrument of Reserve Bank of India? I. Liquidity Adjustment Facility (LAF) II. Reserve Deposit Ratio (RDR)","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":0,"x":"The Liquidity Adjustment Facility is an RBI policy instrument. The reserve–deposit ratio is a bank-behaviour ratio, not an RBI tool.","e":"RBI tools: repo, reverse repo, LAF, MSF, CRR, SLR, OMO.","src":["Junior Clerk 16 Nov 2021 S3"]},{"id":"q2596","q":"Which of the following statement(s) is/are true about the demand deposit, with reference to the banking system in India? I. They are payable by the bank on demand from the accountholder. II. Current and savings account deposits are its examples.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"Demand deposits are payable by the bank whenever the account holder asks; current and savings account deposits are examples. Both statements are correct.","e":"Fixed deposits are time deposits.","src":["Junior Clerk 16 Nov 2021 S3"]},{"id":"q2662","q":"Which of the following is/are the policy instrument of Reserve Bank of India? I. Cash Reserve Ratio (CRR) II. Liquidity Adjustment Facility III. Corridor","o":["I and II","II and III","Only III","I, II and III"],"a":3,"x":"Cash Reserve Ratio, Liquidity Adjustment Facility and the corridor (band between reverse repo/SDF and MSF rates) are all RBI monetary policy instruments.","e":"","src":["Junior Clerk 16 Nov 2021 S2"]},{"id":"q2664","q":"The size of the 200 rupees note of the Mahatma Gandhi (New) Series is _____.","o":["62 mm × 143 mm","62 mm × 144 mm","66mm × 146 mm","64 mm × 142 mm"],"a":2,"x":"The ₹200 note of the Mahatma Gandhi (New) series (bright yellow, Sanchi Stupa motif) measures 66 mm × 146 mm.","e":"","src":["Junior Clerk 16 Nov 2021 S2"]},{"id":"q2666","q":"Which of the following statement(s) is/are true regarding Currency Deposit Ratio (CDR)? I. It reflects people’s preference for liquidity. II. It is a purely behavioural parameter which depends, on the seasonal pattern of expenditure.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"The currency–deposit ratio reflects people's preference for holding cash (liquidity) and depends on behaviour such as seasonal spending, e.g. festivals. Both statements are correct (NCERT).","e":"CDR rises in festival seasons.","src":["Junior Clerk 16 Nov 2021 S2"]},{"id":"q1296","q":"Which of the following committee's recommendations led to the formation of NABARD?","o":["Shri Homi Sethna Committee","Shri Naresh Chandra Committee","Shri Dharma Vira Committee","Shri B. Sivaraman Committee"],"a":3,"x":"NABARD was set up in 1982 on the advice of the CRAFICARD committee headed by B. Sivaraman.","e":"The Narasimham Committee recommended the RRBs (1975).","src":["Stenographer 19 Apr 2021 S1"]},{"id":"q1343","q":"Which among the following banks was inaugurated by Mahatma Gandhi in 1919?","o":["Union Bank of India","State Bank of India","Central Bank of India","Punjab National Bank"],"a":0,"x":"Union Bank of India, founded in Bombay in 1919, was inaugurated by Mahatma Gandhi.","e":"It was nationalised in 1969.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q2751","q":"_____________is the amount of funds that the banks have to keep with the Reserve Bank of India.","o":["Cash Reserve Ratio","Repo Rate","Reverse Repo Rate","Bank Rate"],"a":0,"x":"The Cash Reserve Ratio is the share of deposits banks must keep as cash with the RBI.","e":"CRR: with the RBI; SLR: kept by the bank itself.","src":["Ahlmad 16 Oct 2021 S2"]},{"id":"q2753","q":"National Bank for Agriculture and Rural Development (NABARD) was founded in _________.","o":["1988","1993","1982","1975"],"a":2,"x":"NABARD was set up on 12 July 1982 on the recommendation of the Shivaraman Committee.","e":"","src":["Ahlmad 16 Oct 2021 S2"]},{"id":"q0901","q":"In which of the following years did NABARD initiate the pilot project for linking 500 groups in India?","o":["1995","1992","1990","2000"],"a":1,"x":"NABARD started the SHG–Bank Linkage pilot project in 1992 to link 500 self-help groups with banks.","e":"It grew into the world's largest microfinance programme.","src":["PRT 17 Feb 2026 S3"]},{"id":"q0963","q":"What can the central bank do to increase money supply in the economy?","o":["Decreasing the amount of funds","Increasing Cash reserve ratio","Increasing bank rate","Decreasing bank rate"],"a":3,"x":"Lowering the bank rate makes borrowing from the central bank cheaper, so banks lend more and money supply rises. Raising CRR or bank rate does the opposite.","e":"Cheaper money = more money.","src":["PRT 18 Feb 2026 S3"]},{"id":"q1213","q":"Equity capital and reinvested earnings are part of which component of the capital account?","o":["Direct investment","External assistance","External borrowing","Portfolio investment"],"a":0,"x":"Foreign direct investment in the capital account includes equity capital, reinvested earnings and other capital. Portfolio investment is share and bond buying without a controlling stake.","e":"FDI usually means a lasting interest, commonly 10% or more of equity.","src":["PRT 31 Mar 2026 S2"]},{"id":"q1372","q":"In which year did the Deposit Insurance Corporation start functioning?","o":["1962","1963","1965","1964"],"a":0,"x":"The Deposit Insurance Corporation began work on 1 January 1962; it merged with the Credit Guarantee Corporation in 1978 to form the DICGC.","e":"Deposits are now insured up to ₹5 lakh per depositor per bank (since 2020).","src":["TGT 24 Jun 2023 S2"]},{"id":"q1383","q":"As per RBI guidelines for licensing small finance banks in the private sector, the promoter's minimum initial share in paid-up equity capital shall be at least ______.","o":["45 per cent","50 per cent","60 per cent","40 per cent"],"a":3,"x":"Under the RBI's small finance bank licensing guidelines, promoters must initially hold at least 40% of paid-up equity capital, reduced over time.","e":"Small finance banks must lend 75% of net credit to priority sectors.","src":["TGT 24 Jun 2023 S2"]},{"id":"q1406","q":"Which of the following terms is used for the rate at which commercial banks borrow money by selling their securities to the Reserve Bank of India?","o":["Repo rate","Reverse bank rate","Bank rate","Reverse repo rate"],"a":0,"x":"The repo rate is the rate at which the RBI lends to commercial banks against securities; banks sell securities to the RBI with an agreement to buy them back.","e":"Reverse repo is the rate at which the RBI borrows from banks.","src":["TGT 25 Jun 2023 S1"]},{"id":"q1483","q":"In which year was ICICI formed at the initiative of the World Bank, the Government of India and representatives of Indian industry?","o":["1982","1975","1955","1966"],"a":2,"x":"ICICI (Industrial Credit and Investment Corporation of India) was formed in 1955 at the initiative of the World Bank, the Government of India and Indian industry.","e":"ICICI Bank came later (1994); the two merged in 2002.","src":["TGT 7 Feb 2024 S2"]},{"id":"q1502","q":"What is the difference between the interest rate paid by banks to depositors and the interest rate charged from borrowers called?","o":["Profit margin","Spread","Cash reserve","Liquidity ratio"],"a":1,"x":"The spread (net interest margin) is the gap between the interest banks charge borrowers and the interest they pay depositors.","e":"Lending rate 10% − deposit rate 6% = 4% spread.","src":["TGT 29 Aug 2025"]},{"id":"q1527","q":"In microfinance in India, what is the significance of the 'Joint Liability Group (JLG)' model?","o":["It ensures compliance with environmental sustainability standards.","It provides government subsidies to support agricultural investment.","It enables group-based lending to reduce credit risk and increase repayment rates.","It allows MFIs to diversify their loan portfolios across sectors."],"a":2,"x":"In the Joint Liability Group model, 4–10 borrowers guarantee each other's loans. The group pressure cuts credit risk and raises repayment rates without collateral.","e":"NABARD has promoted JLGs for tenant farmers since 2006.","src":["TGT 24 Aug 2025 S3"]},{"id":"q1544","q":"Which of the following is NOT a function of money in an economy?","o":["Unit of labour","Medium of exchange","Standard of deferred payment","Store of value"],"a":0,"x":"Money works as a medium of exchange, a unit of account (not a 'unit of labour'), a store of value and a standard of deferred payment.","e":"Barter fails without a 'double coincidence of wants', which money solves.","src":["TGT 31 Aug 2025 S1"]},{"id":"q0798","q":"Which of the following organisations are involved in the bi-lateral cooperation programme, 'Rural Financial Institutions Programme' (RFIP), to facilitate effective financial inclusion of low-income households in India?","o":["NABARD and Cooperative for Assistance and Relief Everywhere","RBI and United Nations Development Programme","SIDBI and World Bank","NABARD and German Society for International Cooperation"],"a":3,"x":"The Rural Financial Institutions Programme (RFIP) was a bilateral Indo-German programme between NABARD and GIZ (German Society for International Cooperation) to widen financial inclusion.","e":"GIZ is Germany's development cooperation agency.","src":["PGT 11 Jul 2025 S1"]},{"id":"q0846","q":"Which institution is primarily responsible for providing and regulating credit for the promotion of agriculture and rural development in India?","o":["Securities and Exchange Board of India (SEBI)","State Level Bankers Committee (SLBC)","State Bank of India (SBI)","National Bank for Agriculture and Rural Development (NABARD)"],"a":3,"x":"NABARD (1982) is the apex institution for credit for agriculture and rural development.","e":"It refinances cooperative banks and RRBs.","src":["PGT 14 Jul 2025"]}]},{"id":"planning","n":"Planning, Budget and Reforms","qs":[{"id":"q0015","q":"What was the main focus of the First Five-Year Plan?","o":["Agriculture","Nuclear power","Heavy industries","Tourism"],"a":0,"x":"The First Five-Year Plan (1951–56), built on the Harrod–Domar model, gave top priority to agriculture and irrigation after the food shortages of Partition.","e":"The Second Plan (1956–61, Mahalanobis model) switched the focus to heavy industry.","src":["ASO 18 Aug 2025 S1"]},{"id":"q0053","q":"What was a key technological advancement of the Green Revolution?","o":["The development of organic fertilisers","The reduction in the use of chemical pesticides","The introduction of high-yielding variety (HYV) seeds","The decrease in irrigation practices"],"a":2,"x":"The Green Revolution of the mid-1960s was driven by high-yielding variety (HYV) seeds, especially wheat and rice, used with fertilisers, pesticides and assured irrigation.","e":"M. S. Swaminathan is called the father of India's Green Revolution; Norman Borlaug developed the Mexican dwarf wheat.","src":["ASO 18 Aug 2025 S2"]},{"id":"q0129","q":"The policy of import substitution promotes ______.","o":["the use of only those goods which are produced within the country","the use of only imported goods for public sector activities","the export of those goods which other countries prefer to import","the production of goods which are generally imported"],"a":3,"x":"Import substitution means producing at home the goods the country used to import, usually behind tariffs, to save foreign exchange and build industry.","e":"India followed it from the Second Plan until the 1991 reforms.","src":["ASO 19 Aug 2025 S2"]},{"id":"q0208","q":"Which of the following is NOT an effect of the Green Revolution?","o":["Attaining marketable surplus","Benefit to low income groups","Decrease in agricultural productivity","Buffer stock of food grains"],"a":2,"x":"The Green Revolution raised agricultural productivity, created marketable surpluses and built food buffer stocks. A fall in productivity was not an effect.","e":"Its downsides were regional inequality and soil and water damage.","src":["ASO 20 Aug 2025 S1"]},{"id":"q0267","q":"Which body was established as an extra-constitutional advisory agency to support the union in policy planning?","o":["Supreme Court of India","Election Commission","Planning Commission (now NITI Aayog)","Finance Commission"],"a":2,"x":"The Planning Commission (1950) was extra-constitutional and non-statutory, set up by a Cabinet resolution. NITI Aayog replaced it on 1 January 2015.","e":"The Finance Commission is constitutional (Article 280).","src":["ASO 20 Aug 2025 S2"]},{"id":"q0290","q":"Which of the following was a common goal of India's various Five-Year Plans?","o":["Expansion of the service sector","Self-reliance","Dependence on imports","Decrease in agricultural production"],"a":1,"x":"Self-reliance was a common goal of India's Five-Year Plans, along with growth, modernisation and equity.","e":"The Fourth Plan (1969–74) stressed 'growth with stability and progressive achievement of self-reliance'.","src":["ASO 20 Aug 2025 S3"]},{"id":"q0407","q":"Which major policy, implemented in 2011, aims to increase the growth of the industrial sector in India?","o":["National Agricultural Policy","Industrial Licensing Policy","Special Economic Zones Act","National Manufacturing Policy"],"a":3,"x":"The National Manufacturing Policy (2011) aimed to raise manufacturing to 25% of GDP and create 100 million jobs, including through National Investment and Manufacturing Zones.","e":"Make in India (2014) continued the same goals.","src":["ASO 22 Aug 2025 S1"]},{"id":"q0459","q":"The first phase of the Green Revolution in India was primarily focussed on _________________.","o":["green vegetable production","oil seed production","wheat production","pulses production"],"a":2,"x":"The first phase of the Green Revolution (1960s) focused mainly on wheat, in Punjab, Haryana and western Uttar Pradesh.","e":"Rice got the benefits later; pulses and oilseeds lagged.","src":["ASO 27 Aug 2025 S1"]},{"id":"q1607","q":"When was the Economic Survey decoupled from the Indian Union Budget?","o":["1964","1954","1951","1960"],"a":0,"x":"The Economic Survey was first presented in 1950-51 as part of the Union Budget and was separated from the Budget documents in 1964.","e":"It is prepared by the Chief Economic Adviser and presented a day before the Budget.","src":["Patwari 17 Sep 2022 S2"]},{"id":"q0489","q":"Which among the following is not a component of fiscal policies adopted by the Government?","o":["Cash reserve ratio","Government spending","Taxes","Subsidies"],"a":0,"x":"Fiscal policy is the government's use of spending, taxes and subsidies. CRR is a monetary policy tool of the RBI.","e":"Monetary policy: repo rate, CRR, SLR, open market operations.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S1"]},{"id":"q0605","q":"A _____________ was originally defined as a tax on all spot conversions of one currency into another.","o":["Tobin tax","Pigouvian tax","Octroi tax","Corporate tax"],"a":0,"x":"The Tobin tax, proposed by James Tobin (1972), was a tax on all spot conversions of one currency into another, meant to curb currency speculation.","e":"A Pigouvian tax targets negative externalities, such as a carbon tax.","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S2"]},{"id":"q0607","q":"The Union Budget was presented at 5 pm in the Parliament till the year __________.","o":["1995","2001","2000","2005"],"a":2,"x":"The Union Budget was presented at 5 pm until 2000; from 2001, Yashwant Sinha shifted it to 11 am.","e":"Since 2017 it has been presented on 1 February.","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S2"]},{"id":"q0609","q":"Who among the following was the first woman to have presented the budget in the parliament?","o":["Sonia Gandhi","Pratibha Patil","Indira Gandhi","Nirmala Sitharaman"],"a":2,"x":"Indira Gandhi was the first woman to present the Union Budget (1970), as Prime Minister holding Finance.","e":"Nirmala Sitharaman is the first full-time woman Finance Minister (2019).","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S2"]},{"id":"q0646","q":"After India became independent in 1947, the country's first Finance Minister, __________ presented the first budget.","o":["Yashwant Sinha","Manmohan Singh","Morarji Desai","Shanmukham Chetty"],"a":3,"x":"R. K. Shanmukham Chetty, independent India's first Finance Minister, presented its first budget on 26 November 1947.","e":"The first budget of the Republic (1950) was presented by John Mathai.","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S3"]},{"id":"q0648","q":"Which among the following is an example of indirect tax?","o":["Income tax","Sales tax","Gift tax","Expenditure tax"],"a":1,"x":"Sales tax is an indirect tax: it is paid by the consumer but collected and deposited by the seller. Income, gift and expenditure taxes are direct.","e":"GST (2017) replaced most indirect taxes, including state sales tax (VAT).","src":["Junior Assistant 25 Aug 2021","Junior Assistant 25 Aug 2021 S3"]},{"id":"q0686","q":"Who among the following holds the record of presenting the most number of financial budgets as of April 2020?","o":["Yashwant Sinha","Nirmala Sitharaman","Morarji Desai","Pranab Mukherjee"],"a":2,"x":"Morarji Desai presented the most Union Budgets: ten in all, including two interim budgets.","e":"Nirmala Sitharaman presented her 8th consecutive budget in 2025.","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S1"]},{"id":"q0688","q":"Which among the following taxes is imposed on the bodies that have negative externality?","o":["Pigouvian tax","Tobin tax","Octroi tax","Smith tax"],"a":0,"x":"A Pigouvian tax (after Arthur Pigou) is levied on activities with negative externalities, so polluters pay for the harm they cause.","e":"A carbon tax is a Pigouvian tax.","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S1"]},{"id":"q0725","q":"Amongst the following, who presents the Union Budget of India in Parliament?","o":["Chief Economic Advisor","Finance Secretary","Finance Minister","Prime Minister"],"a":2,"x":"The Union Finance Minister presents the Union Budget (Annual Financial Statement, Article 112) in Parliament.","e":"The first Union Budget of independent India was presented in 1947.","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S2"]},{"id":"q0726","q":"Amongst the following, who became the first Chairman of the Planning Commission in 1950?","o":["Sardar Vallabhbhai Patel","Jawaharlal Nehru","Indira Gandhi","Morarji Desai"],"a":1,"x":"Jawaharlal Nehru, as Prime Minister, was the first chairman of the Planning Commission (15 March 1950); Gulzarilal Nanda was the first deputy chairman.","e":"The Prime Minister also chairs NITI Aayog.","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S2"]},{"id":"q0754","q":"In India, as of April 2020, which one of the following taxes is levied at both the central and the state level?","o":["Excise duty","Goods and Service Tax","Basic customs duty","Octroi"],"a":1,"x":"GST is levied by both the Centre (CGST) and the states (SGST) on intra-state supplies; IGST covers inter-state supplies.","e":"The 101st Amendment (2016) made the dual GST possible.","src":["Junior Assistant 31 Aug 2021","Junior Assistant 31 Aug 2021 S2"]},{"id":"q1742","q":"Which of the following is an indirect tax?","o":["Wealth tax","Income tax","Estate duty","Custom duties"],"a":3,"x":"An indirect tax is paid by one person but its burden passes to another, e.g. customs duty, GST and excise. Income, wealth and estate taxes are direct.","e":"Direct = on income or wealth; indirect = on goods and services.","src":["Junior Clerk 11 Nov 2021 S1"]},{"id":"q1787","q":"Which of the following statement is correct regarding about the proportional income tax? I. It acts as an automatic stabiliser. II. Firms are taxed on a proportional basis, where the tax rate is a particular proportion of profits.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"NCERT Macroeconomics: a proportional income tax acts as an automatic stabiliser (tax falls as income falls), and firms are taxed on a proportional basis as a fixed share of profits.","e":"Automatic stabilisers soften booms and slumps without new decisions.","src":["Junior Clerk 11 Nov 2021 S2"]},{"id":"q1941","q":"Which of the following statement(s) is/are true about the government budget? I. It gives a statement of the receipts and borrowing of the government. II. Revenue budget is one of its components.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":1,"x":"The government budget is an annual statement of estimated receipts and expenditure (Article 112), not of 'receipts and borrowing'; it has two parts, the revenue budget and the capital budget.","e":"Revenue budget + capital budget = Union Budget.","src":["Junior Clerk 12 Nov 2021 S1"]},{"id":"q1980","q":"When was the Industrial Policy Resolution (IPR) adopted in India?","o":["1960","1950","1956","1965"],"a":2,"x":"The Industrial Policy Resolution of 1956 divided industries into three schedules and gave the public sector the leading role; it followed the first IPR of 1948.","e":"IPR 1948 → IPR 1956 → New Industrial Policy 1991.","src":["Junior Clerk 12 Nov 2021 S2"]},{"id":"q2124","q":"Which of the following statement is true regarding NITI Aayog? I. NITI Aayog is the premier policy ‘Think Tank’ of the Government of India. II. It was formed in 2015.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":2,"x":"NITI Aayog, formed on 1 January 2015 to replace the Planning Commission, is the Government of India's premier policy think tank.","e":"NITI = National Institution for Transforming India.","src":["Junior Clerk 13 Nov 2021 S2"]},{"id":"q2392","q":"Which of the following is known as the \"Economic Constitution of India\"?","o":["Industrial Policy Resolution of 1948","Industrial Policy Statement of 1956","Industrial Policy of 1991","Industrial Policy Resolution 1995"],"a":1,"x":"The Industrial Policy Resolution of 1956 is called the 'Economic Constitution of India'; it gave the public sector the leading role under the Second Plan.","e":"It sorted industries into Schedules A, B and C.","src":["Junior Clerk 15 Nov 2021 S1"]},{"id":"q2485","q":"In which of the following circumstances high Fiscal deficit could be good for an economy?","o":["When external grants increases","When mode of interest payment decreases","If the spending on productive assests increases","When GST collection decreases"],"a":2,"x":"A high fiscal deficit can be good if the borrowing is spent on productive assets such as infrastructure, which raise future growth and income.","e":"Borrowing for consumption is worse than borrowing for capital assets.","src":["Junior Clerk 15 Nov 2021 S3"]},{"id":"q2595","q":"What is the correct measurement of Gross Fiscal Deficit?","o":["Total expenditure + (Revenue receipts – Non-debt creating capital receipts)","Total expenditure – (Revenue receipts + Non-debt creating capital receipts)","Total expenditure + Non-debt creating capital receipts","Total expenditure – Non-debt creating capital receipts"],"a":1,"x":"Gross Fiscal Deficit = Total expenditure − (Revenue receipts + Non-debt creating capital receipts).","e":"It equals the government's total borrowing need.","src":["Junior Clerk 16 Nov 2021 S3","Junior Clerk 17 Nov 2021 S2"]},{"id":"q2612","q":"Which organization releases SDG (Sustainable Development Goals) India Index?","o":["NITI Aayog","Reserve Bank of India","Defence Research and Development Organisation","Telecom Regulatory Authority of India"],"a":0,"x":"NITI Aayog publishes the SDG India Index, which ranks states on the Sustainable Development Goals (since 2018).","e":"","src":["Junior Clerk 16 Nov 2021 S3"]},{"id":"q2665","q":"Which of the following statement(s) is/are NOT true regarding Fiscal Responsibility and Budget Management Act, 2003 (FRBMA)? I. The rules under the Act were notified with effect from July, 2004. II. The Act mandates the central government to take appropriate measures to reduce fiscal deficit and eliminate revenue deficit.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":3,"x":"Both statements are true: the FRBM Act, 2003's rules were notified from 5 July 2004, and it requires the Centre to reduce the fiscal deficit and eliminate the revenue deficit. So neither is 'not true'.","e":"FRBM = Fiscal Responsibility and Budget Management.","src":["Junior Clerk 16 Nov 2021 S2"]},{"id":"q1302","q":"What was the duration of the Second Five Year Plan?","o":["1957-62","1958-63","1955-60","1956-61"],"a":3,"x":"The Second Five-Year Plan ran from 1956 to 1961, stressing industrialisation on the Mahalanobis model.","e":"First Plan: 1951–56. Third Plan: 1961–66.","src":["Stenographer 19 Apr 2021 S1"]},{"id":"q1333","q":"The Goods and Services Tax was introduced in ________ in India.","o":["2017","2018","2019","2016"],"a":0,"x":"GST was introduced in India on 1 July 2017, replacing many central and state indirect taxes.","e":"GST Day is observed on 1 July.","src":["Stenographer 23 Apr 2021 S2"]},{"id":"q0899","q":"Which of the following is NOT a benefit of the LPG reforms?","o":["Increased foreign investment","Access to modern technology","Reduction in competition","Growth in GDP"],"a":2,"x":"The 1991 LPG (liberalisation, privatisation, globalisation) reforms brought more foreign investment, access to modern technology and faster GDP growth. They increased competition, not reduced it.","e":"The reforms were led by PM P. V. Narasimha Rao and Finance Minister Manmohan Singh.","src":["PRT 16 Feb 2026 S3"]},{"id":"q0900","q":"Which leader initiated the Garibi Hatao (Eradicate Poverty) initiative in the 1970s to combat poverty?","o":["Indira Gandhi","Rajiv Gandhi","Atal Bihari Vajpayee","Jawaharlal Nehru"],"a":0,"x":"'Garibi Hatao' (Remove Poverty) was Indira Gandhi's slogan in the 1971 election and became the theme of the Fifth Five Year Plan (1974–79).","e":"The 20-Point Programme followed in 1975.","src":["PRT 16 Feb 2026 S3"]},{"id":"q0936","q":"Outsourcing is one of the important outcomes of which process?","o":["Communism","Liberalisation","Globalisation","Capitalisation"],"a":2,"x":"Outsourcing, where firms hire outside or overseas agencies for services such as call centres and IT, is a major outcome of globalisation.","e":"India became a hub for BPO and IT outsourcing after 1991.","src":["PRT 18 Feb 2026 S1"]},{"id":"q0937","q":"Outsourcing is one of the important outcomes of which process?","o":["Communism","Liberalisation","Globalisation","Capitalisation"],"a":2,"x":"Outsourcing — firms hiring outside agencies, often abroad, for services such as call centres and IT — is a key result of globalisation and cheap communication.","e":"India became a BPO hub after the 1990s.","src":["PRT 18 Feb 2026 S1"]},{"id":"q0999","q":"What was the expected outcome of the trade and investment policy reforms of 1991?","o":["Increased adoption of modern technologies","Reduced efficiency of local industries","Decreased foreign investment","Increased trade barriers"],"a":0,"x":"The 1991 LPG reforms opened trade and foreign investment to bring in modern technology, efficiency and competition.","e":"LPG = Liberalisation, Privatisation, Globalisation (Manmohan Singh budget, July 1991).","src":["PRT 19 Feb 2026 S1"]},{"id":"q1000","q":"Which of the following was a major goal of India's 1991 trade and investment policy reforms?","o":["Promote local handicrafts","Increase population growth","Enhance international competitiveness and attract foreign investments","Eliminate all taxes"],"a":2,"x":"The 1991 trade and investment reforms aimed to make Indian industry internationally competitive and attract foreign investment by cutting tariffs and licensing.","e":"FDI up to 51% was allowed automatically in priority industries in 1991.","src":["PRT 19 Feb 2026 S2"]},{"id":"q1043","q":"What was the maximum investment limit for the classification of small-scale industrial units in India in 1950?","o":["Rupees fifty lakh","Rupees ten lakh","Rupees one crore","Rupees five lakh"],"a":3,"x":"In 1950 a small-scale industrial unit was one with investment up to ₹5 lakh in fixed assets; the limit has been raised many times.","e":"Since 2020 MSMEs are classified by both investment and turnover.","src":["PRT 20 Feb 2026 S1"]},{"id":"q1063","q":"According to the 1979 Task Force on 'Projections of Minimum Needs and Effective Consumption Demand', how was the poverty line defined?","o":["On the basis of literacy rate","On the basis of per capita consumption expenditure","On the basis of unemployment rate","On the basis of income level"],"a":1,"x":"The 1979 Task Force on Minimum Needs and Effective Consumption Demand (Y.K. Alagh) defined the poverty line by per capita consumption expenditure needed for minimum calories (2,400 rural, 2,100 urban).","e":"Later committees: Lakdawala (1993), Tendulkar (2009), Rangarajan (2014).","src":["PRT 20 Feb 2026 S2"]},{"id":"q1098","q":"Since 1991, how have trade policy reforms aimed to affect the competitiveness of Indian goods in international markets?","o":["By increasing government control over trade","By raising tariffs and quantitative restrictions","By lowering tariffs and removing quantitative restrictions","By reducing foreign investment"],"a":2,"x":"Trade reforms since 1991 cut tariffs and removed quantitative restrictions such as import quotas and licences, making Indian goods more competitive abroad.","e":"The rupee was also devalued in July 1991.","src":["PRT 23 Feb 2026 S3"]},{"id":"q1147","q":"Which economic reform in India aimed at liberalising the industrial sector and reducing government control?","o":["Industrial Policy, 1948","New Economic Policy, 1991","Mahatma Gandhi National Rural Employment Guarantee Act (MGNREGA)","Demonetisation"],"a":1,"x":"The New Economic Policy of 1991 liberalised industry: it ended most industrial licensing, cut reserved public-sector areas and opened the economy to foreign investment.","e":"MGNREGA is a rural jobs law; demonetisation (2016) was a currency measure.","src":["PRT 26 Mar 2026 S2"]},{"id":"q1178","q":"Why was NITI Aayog established as a replacement for the Planning Commission?","o":["To limit state participation in national policies","To abolish financial allocation mechanisms","To centralise policymaking in the Union Government","To strengthen cooperative federalism in policy formulation"],"a":3,"x":"NITI Aayog (1 January 2015) replaced the Planning Commission to encourage cooperative federalism: states help shape policy instead of receiving top-down plans.","e":"The Prime Minister is its chairperson; all Chief Ministers sit on its Governing Council.","src":["PRT 31 Mar 2026 S1"]},{"id":"q1206","q":"What is the relationship between liberalisation and globalisation?","o":["Liberalisation is a barrier to globalisation","Liberalisation and globalisation are unrelated","Liberalisation leads to globalisation","Globalisation happens before liberalisation"],"a":2,"x":"Liberalisation (removing restrictions on trade and investment) leads to globalisation (integrating the economy with the world).","e":"India's 1991 reforms: liberalisation → privatisation → globalisation.","src":["PRT 31 Mar 2026 S2"]},{"id":"q1212","q":"The 'Make in India' initiative was launched mainly in response to which national concern?","o":["A sharp decline in economic growth and the need to revive growth through manufacturing and innovation","A steep rise in foreign debt and the need to promote agricultural exports","Pressure from international organisations to liberalise the economy and privatise public enterprises","A widening trade deficit and rising inflation after the 2008 global financial crisis"],"a":0,"x":"'Make in India' (September 2014) answered slowing growth and a weak manufacturing share by pushing investment, innovation and domestic manufacturing.","e":"Its symbol is a lion made of gears.","src":["PRT 31 Mar 2026 S2"]},{"id":"q1216","q":"In which year was the Monopolies and Restrictive Trade Practices Act enacted?","o":["1967","1966","1972","1969"],"a":3,"x":"The Monopolies and Restrictive Trade Practices (MRTP) Act was passed in 1969 (in force 1970); the Competition Act, 2002 replaced it.","e":"The Competition Commission of India enforces the 2002 Act.","src":["PRT 31 Mar 2026 S3"]},{"id":"q1256","q":"The second Five Year Plan in India was formulated on whose ideas?","o":["T.T. Krishnamachari","Prasanta Chandra Mahalanobis","Dr. John Mathai","R.K. Shanmukham Chetty"],"a":1,"x":"The Second Five-Year Plan (1956–61) was based on P. C. Mahalanobis's model, which stressed heavy industry and the public sector.","e":"Mahalanobis founded the Indian Statistical Institute (1931); his birthday, 29 June, is Statistics Day.","src":["PRT 10 Apr 2026 S1"]},{"id":"q1433","q":"Receipts which neither create any liability nor reduce the assets of the government are called ______.","o":["self-assessed receipts","revenue receipts","capital receipts","standard receipts"],"a":1,"x":"Revenue receipts neither create a liability nor reduce the government's assets: taxes, fees, dividends. Capital receipts do (borrowing, disinvestment).","e":"Borrowing creates a liability, so it is a capital receipt.","src":["TGT 25 Jun 2023 S2"]},{"id":"q0762","q":"According to the Industrial Policy Resolution of 1948, which industrial policy model did India adopt?","o":["A mixed economy model with important roles for both the public and private sectors","A purely capitalist model driven by private enterprise","A fully socialist economy with complete state ownership of industries","A laissez-faire model with minimum government intervention in industry"],"a":0,"x":"The Industrial Policy Resolution of 1948 set up a mixed economy, with important roles for both the public and private sectors.","e":"The 1956 Resolution then gave the public sector the leading role.","src":["PGT 25 Sep 2025"]},{"id":"q0780","q":"Why is the Industrial Policy Resolution (IPR) of 1956 often called the 'economic constitution of India'?","o":["Because it began the liberalisation and privatisation of major industries.","Because it introduced a socialist economy and banned foreign investment.","Because it ended private ownership in all major industries.","Because it classified industries into categories and laid the foundation of public-sector-led growth."],"a":3,"x":"The Industrial Policy Resolution of 1956 is called India's 'economic constitution' because it sorted industries into three schedules and made the public sector the base of growth.","e":"Schedule A: exclusive state monopoly (17 industries); B: state-led with private participation; C: private sector.","src":["PGT 25 Sep 2025"]},{"id":"q0827","q":"____________________ means fixing the maximum size of land which could be owned by an individual, with the purpose of reducing the concentration of land ownership in a few hands.","o":["Land ceiling","Unification of land","Land redistribution","Land consolidation"],"a":0,"x":"Land ceiling fixes the maximum land an individual or family may own, so the surplus can go to the landless and ownership is not concentrated.","e":"Land ceiling was a major land reform after Independence, along with zamindari abolition.","src":["PGT 26 Sep 2025"]},{"id":"q0873","q":"The Income Tax Appellate Tribunal (ITAT) handles appeals relating to which category of tax?","o":["Central Goods and Services Tax","Goods and Services Tax","Value Added Tax","Corporate tax"],"a":3,"x":"The Income Tax Appellate Tribunal (1941) hears appeals on direct taxes such as income tax and corporate tax. GST disputes go to the GST Appellate Tribunal.","e":"ITAT was the first tribunal set up in India.","src":["PGT 24 Sep 2025"]}]},{"id":"schemes","n":"Government Schemes and Policies","qs":[{"id":"q0043","q":"What is the ratio of the expenditure for the National Food for Work Programme shared between the Central and State Governments in India?","o":["90 : 10","100 : 0","75 : 25","50 : 50"],"a":1,"x":"The National Food for Work Programme (November 2004, in 150 backward districts) was 100% centrally sponsored. It was merged into MGNREGA in 2006.","e":"MGNREGA's funding is different: the Centre pays all unskilled wages and 75% of material costs.","src":["ASO 18 Aug 2025 S2"]},{"id":"q0062","q":"In which year was the ‘Valmiki Ambedkar Awas Yojana’ launched by the Government of India?","o":["1998","2004","1996","2001"],"a":3,"x":"The Valmiki Ambedkar Awas Yojana (VAMBAY) was launched in December 2001 to build houses for urban slum dwellers.","e":"It was later merged into the JNNURM housing programme.","src":["ASO 18 Aug 2025 S2"]},{"id":"q0172","q":"The Mahatma Gandhi National Rural Employment Guarantee Act (MGNREGA) guarantees how many days of wage employment in a year?","o":["100 days","50 days","200 days","150 days"],"a":0,"x":"MGNREGA (2005) guarantees 100 days of wage employment a year to every rural household whose adults volunteer for unskilled manual work.","e":"If work is not given within 15 days of applying, an unemployment allowance is due.","src":["ASO 19 Aug 2025 S3"]},{"id":"q0227","q":"National Literacy Mission was launched in which of the following years by the Government of India?","o":["1988","1989","1990","1987"],"a":0,"x":"The National Literacy Mission was launched on 5 May 1988 to make adults aged 15–35 functionally literate.","e":"It was followed by Saakshar Bharat (2009).","src":["ASO 20 Aug 2025 S1"]},{"id":"q0240","q":"With reference to the education policies in India, identify whether the following statements are correct or incorrect. A: The National Policy on Education was adopted in the year 1986. B: The National Education Policy (NEP) was adopted in the year 2020.","o":["Both A and B are correct.","A is incorrect and B is correct.","A is correct and B is incorrect.","Both A and B are incorrect."],"a":0,"x":"Both are correct: the National Policy on Education was adopted in 1986 (modified 1992), and the National Education Policy in 2020.","e":"NEP 2020 brings the 5+3+3+4 school structure.","src":["ASO 20 Aug 2025 S1"]},{"id":"q0253","q":"Which government initiative focuses on self-employment opportunities in rural India?","o":["Deen Dayal Antyodaya Yojana – National Rural Livelihoods Mission (DAY-NRLM)","National Rural Livelihood Promotion Society (NRLPS)","Sagarmala Project","Mahatama Gandhi Gramin Basti Yojana Scheme (MGGBYS)"],"a":0,"x":"DAY-NRLM (Aajeevika, 2011) builds self-employment for rural poor households, mainly through women's Self-Help Groups.","e":"The urban version is DAY-NULM.","src":["ASO 20 Aug 2025 S2"]},{"id":"q1593","q":"Which of the following programs was launched by the Govt. of India to provide connectivity to unconnected habitations as part of a poverty reduction strategy?","o":["Pradhan Mantri Gram Sadak Yojana","Pradhan Mantri Gram Connectivity Scheme","PM Rural Road Transport Network Program","PM Gram Setu Yojana"],"a":0,"x":"Pradhan Mantri Gram Sadak Yojana (25 December 2000) gives all-weather road links to unconnected rural habitations as part of poverty reduction.","e":"It is run by the Ministry of Rural Development.","src":["Patwari 20 Aug 2022 S2"]},{"id":"q0573","q":"The Swachh Bharat Abhiyan (Urban) lies under the ______________.","o":["Ministry of Drinking Water and Sanitation","Ministry of External Affairs","Ministry of Housing and Urban Affairs","Ministry of Home Affairs"],"a":2,"x":"Swachh Bharat Mission (Urban) is run by the Ministry of Housing and Urban Affairs; SBM (Grameen) by the Jal Shakti Ministry's Department of Drinking Water and Sanitation.","e":"Swachh Bharat was launched on 2 October 2014.","src":["Junior Assistant 21 Aug 2021","Junior Assistant 21 Aug 2021 S3"]},{"id":"q2070","q":"Which of the following statement is NOT correct regarding Minimum Support Price? I. It is declared by the government every year after the harvesting season. II. Minimum Support Price is the price at which government purchases crops for the farmers, to safeguard the interests of the farmers.","o":["Only I","Only II","Both I and II","Neither I nor II"],"a":0,"x":"Minimum Support Price is announced BEFORE the sowing season, not after harvest, so statement I is wrong; MSP is the price at which the government buys crops to protect farmers.","e":"MSP is recommended by the CACP.","src":["Junior Clerk 13 Nov 2021 S1"]},{"id":"q2150","q":"What is the full form of the PM-KUSUM Yojana?","o":["Pradhan Mantri - Kendriya Urja Evan Sinchai Utthan","Pradhan Mantri-Krishi Urja Suraksha evam Utthan","Pradhan Mantri-Kisan Urja Suraksha evam Utthan Mahabhiyan","Pradhan Mantri-Kaushal Utthan"],"a":2,"x":"PM-KUSUM stands for Pradhan Mantri Kisan Urja Suraksha evam Utthaan Mahabhiyan (2019); it supports solar pumps and solar power plants for farmers.","e":"Run by the Ministry of New and Renewable Energy.","src":["Junior Clerk 13 Nov 2021 S3"]},{"id":"q2521","q":"In which year was the National Infrastructure Pipeline (NIP) announced by the Finance Minister of India?","o":["2016","2017","2018","2019"],"a":3,"x":"The National Infrastructure Pipeline, a ₹111 lakh crore infrastructure plan for 2020–25, was announced in December 2019.","e":"","src":["Junior Clerk 16 Nov 2021 S1"]},{"id":"q2523","q":"What is the SWAMITVA Yojana related to?","o":["Agricultural marketing","Ensuring fixed income to the unemployed in the rural areas","Mapping residential land ownership in the rural sector","Giving agricultural land to the landless farmers"],"a":2,"x":"SVAMITVA (2020) maps rural residential (abadi) land with drones and gives owners property cards.","e":"Run by the Ministry of Panchayati Raj.","src":["Junior Clerk 16 Nov 2021 S1"]},{"id":"q0897","q":"In which year was the 'National Social Assistance Scheme' launched to provide financial assistance to the elderly, widows and persons with disabilities?","o":["1995","1980","2015","2010"],"a":0,"x":"The National Social Assistance Programme (NSAP) began on 15 August 1995, giving pensions to the elderly, widows and persons with disabilities.","e":"It is a centrally sponsored scheme under Article 41 (DPSP).","src":["PRT 16 Feb 2026 S3"]},{"id":"q0904","q":"What is the main objective of the Swachh Bharat Mission (Gramin)?","o":["Open defecation free villages","Providing irrigation","Rural electrification","Providing gas connections"],"a":0,"x":"Swachh Bharat Mission (Gramin), launched on 2 October 2014, aimed to make villages Open Defecation Free; Phase II (ODF Plus) adds waste management.","e":"Run by the Department of Drinking Water and Sanitation.","src":["PRT 17 Feb 2026 S3"]},{"id":"q0919","q":"Which of the following is the main objective of the PM SVANidhi scheme?","o":["To provide support to old age persons","To provide financial support to street vendors for their business growth","To provide accommodation support to shelterless people","To provide free education to street vendors' children"],"a":1,"x":"PM SVANidhi (June 2020) gives street vendors collateral-free working-capital loans (₹10,000 then ₹20,000 then ₹50,000) with an interest subsidy.","e":"Run by the Ministry of Housing and Urban Affairs.","src":["PRT 17 Feb 2026 S3"]},{"id":"q0941","q":"What is the main objective of the Digital India initiative launched in 2015?","o":["To reduce the number of online services available in villages","To transform India into a digitally empowered society and economy","To provide extensive internet facilities only in urban and semi-urban areas","To promote traditional farming methods in rural communities"],"a":1,"x":"Digital India (launched 1 July 2015) aims to transform India into a digitally empowered society and knowledge economy.","e":"Its three pillars: digital infrastructure, governance and services on demand, digital empowerment of citizens.","src":["PRT 18 Feb 2026 S2"]},{"id":"q0966","q":"In which year was the 'Prime Minister's Employment Generation Programme (PMEGP)' launched by the Government of India?","o":["2005","2002","2008","2012"],"a":2,"x":"The Prime Minister's Employment Generation Programme (PMEGP) was launched in 2008 by merging PMRY and REGP; KVIC implements it.","e":"It gives credit-linked subsidies for new micro-enterprises.","src":["PRT 18 Feb 2026 S3"]},{"id":"q0991","q":"Which of the following is NOT a key area of urban development under the Atal Mission for Rejuvenation and Urban Transformation (AMRUT)?","o":["Non-Motorised Urban Transport","Promotion of transshipment hubs","Sewerage and septage management","Green spaces and parks"],"a":1,"x":"AMRUT (2015) focuses on water supply, sewerage and septage, stormwater drainage, non-motorised urban transport and green spaces and parks. Transshipment hubs are a port or shipping matter.","e":"AMRUT 2.0 (2021) aims for 'water-secure' cities.","src":["PRT 19 Feb 2026 S1"]},{"id":"q1008","q":"The Bharatmala Project is related to the development of which type of infrastructure?","o":["Airports","Smart Cities","Railways","Highways"],"a":3,"x":"Bharatmala Pariyojana (2017) is a road and highway development programme; Sagarmala is its port counterpart.","e":"Bharatmala = roads; Sagarmala = ports.","src":["PRT 19 Feb 2026 S2"]},{"id":"q1057","q":"In which year was the 'Pradhan Mantri Garib Kalyan Anna Yojana (PM-GKAY)' launched by the Government of India?","o":["2015","2022","2020","2017"],"a":2,"x":"Pradhan Mantri Garib Kalyan Anna Yojana (PM-GKAY) was launched in April 2020 during COVID-19 to give free food grains; from 2024 it continues for five years.","e":"It covers NFSA beneficiaries (about 81 crore people).","src":["PRT 20 Feb 2026 S2"]},{"id":"q1130","q":"Apart from PM-GKAY, what other benefit do families covered under the National Food Security Act (NFSA) in India receive?","o":["Free health services","Subsidised food grains","Free cooking gas cylinders","Cash subsidy"],"a":1,"x":"Under the National Food Security Act, 2013, eligible households get subsidised food grains (rice ₹3, wheat ₹2, coarse grains ₹1 per kg); since January 2023 these grains are free under PM-GKAY.","e":"Antyodaya households get 35 kg per month; priority households 5 kg per person.","src":["PRT 26 Mar 2026 S1"]},{"id":"q1132","q":"The 'Rural Electrification Scheme' was launched to provide electricity to whom?","o":["Only urban families","Commercial buildings","All remote villages","Only rural industrial areas"],"a":2,"x":"Rural electrification schemes (RGGVY 2005, then DDUGJY 2014) aimed to bring electricity to all villages, including remote ones; India declared 100% village electrification in April 2018.","e":"Saubhagya (2017) aimed at every household.","src":["PRT 26 Mar 2026 S1"]},{"id":"q1134","q":"Which programme was launched in 1990–91 to tackle land degradation in India?","o":["National Watershed Development Project for Rainfed Areas","MGNREGA","AMRUT Mission","Pradhan Mantri Gram Sadak Yojana"],"a":0,"x":"The National Watershed Development Project for Rainfed Areas (NWDPRA) began in 1990–91 to fight land degradation and raise productivity in rainfed areas.","e":"Watershed approach = treat land and water of a whole catchment together.","src":["PRT 26 Mar 2026 S1"]},{"id":"q1157","q":"When was the Pradhan Mantri Garib Kalyan Yojana (PMGKY) package announced?","o":["April 2021","March 2020","January 2014","February 2016"],"a":1,"x":"The Pradhan Mantri Garib Kalyan Yojana relief package of ₹1.7 lakh crore was announced on 26 March 2020 at the start of the COVID-19 lockdown.","e":"Free grain under it later became PM-GKAY.","src":["PRT 26 Mar 2026 S3"]},{"id":"q1204","q":"What is the name of the national ration card portability initiative launched to ensure food security for all, including internal migrants, in India?","o":["One Nation, One Ration Card","One Citizen, One Card","One Nation, One Card","One Ration Card, One Citizen"],"a":0,"x":"'One Nation, One Ration Card' (2019) lets NFSA beneficiaries, including migrant workers, draw their ration from any fair price shop in India.","e":"It works through Aadhaar-seeded ePoS machines.","src":["PRT 31 Mar 2026 S2"]},{"id":"q1270","q":"Which of the following schemes of the Government of India provides pensions to poor elderly individuals who lack support from caregivers?","o":["National Social Assistance Programme","Mahatma Gandhi National Rural Employment Guarantee Act","National Rural Employment Guarantee Scheme","Pradhan Mantri Awas Yojana"],"a":0,"x":"The National Social Assistance Programme (15 August 1995) gives pensions to poor elderly people, widows and persons with disabilities, including the Indira Gandhi National Old Age Pension Scheme.","e":"It is run by the Ministry of Rural Development.","src":["PRT 10 Apr 2026 S1"]},{"id":"q1272","q":"The 'Prime Minister's Employment Generation Programme (PMEGP)' is administered by which of the following Ministries of the Government of India?","o":["Ministry of Micro, Small and Medium Enterprises","Ministry of Rural Development","Ministry of Labour and Employment","Ministry of Home Affairs"],"a":0,"x":"The Prime Minister's Employment Generation Programme (2008) is run by the Ministry of MSME through KVIC; it gives credit-linked subsidies to set up small enterprises.","e":"It merged the PMRY and REGP schemes.","src":["PRT 10 Apr 2026 S1"]},{"id":"q1526","q":"Which non-farm employment is associated with Operation Flood?","o":["Fisheries","Information technology","Horticulture","Animal husbandry"],"a":3,"x":"Operation Flood (1970, NDDB, led by Dr Verghese Kurien) was the White Revolution in dairying, a form of animal husbandry, which made India the world's largest milk producer.","e":"National Milk Day is 26 November, Kurien's birthday.","src":["TGT 24 Aug 2025 S3"]},{"id":"q0874","q":"Which of these schemes/programmes are implemented by the Ministry of Rural Development? 1. Atmanirbhar Bharat Rozgar Yojana 2. Mahatma Gandhi National Rural Employment Guarantee Scheme","o":["Only 2","Both 1 and 2","Neither 1 nor 2","Only 1"],"a":0,"x":"MGNREGA is run by the Ministry of Rural Development; the Atmanirbhar Bharat Rozgar Yojana (2020) was run by the Ministry of Labour and Employment through EPFO.","e":"MGNREGA guarantees 100 days of wage work per rural household.","src":["PGT 24 Sep 2025"]},{"id":"q0877","q":"Which ministry is responsible for implementing the Smart Cities Mission?","o":["Ministry of Transport","Ministry of Finance","Ministry of Rural Development","Ministry of Urban Development"],"a":3,"x":"The Smart Cities Mission (2015) is run by the Ministry of Housing and Urban Affairs (formerly Urban Development).","e":"AMRUT and PMAY-Urban are run by the same ministry.","src":["PGT 24 Sep 2025"]}]}]});
